/* Tongue Twister data: sentences from the Unicode UDHR collection, families and map points from Glottolog, speaker numbers from the linked sources. */
(window.LudusData = window.LudusData || {}).tongue = [{"name":"English","aka":[],"family":"Indo-European","branch":"Germanic","script":"Latin","lat":53.0,"lon":-1.0,"speakers":380000000,"region":"Europe","samples":["All human beings are born free and equal in dignity and rights. They are endowed with reason and conscience and should act towards one another in a spirit of brotherhood.","Everyone has the right to life, liberty and the security of person.","No one shall be subjected to arbitrary arrest, detention or exile."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_eng.xml","speakers":"https://en.wikipedia.org/wiki/English_language","glottolog":"https://glottolog.org/resource/languoid/id/stan1293"}},{"name":"French","aka":["Français"],"family":"Indo-European","branch":"Romance","script":"Latin","lat":48.0,"lon":2.0,"speakers":74000000,"region":"Europe","samples":["Tous les êtres humains naissent libres et égaux en dignité et en droits. Ils sont doués de raison et de conscience et doivent agir les uns envers les autres dans un esprit de fraternité.","Tout individu a droit à la vie, à la liberté et à la sûreté de sa personne.","Nul ne peut être arbitrairement arrêté, détenu ni exilé."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_fra.xml","speakers":"https://en.wikipedia.org/wiki/French_language","glottolog":"https://glottolog.org/resource/languoid/id/stan1290"}},{"name":"Spanish","aka":["Español","Castilian"],"family":"Indo-European","branch":"Romance","script":"Latin","lat":40.4414,"lon":-1.1179,"speakers":519000000,"region":"Europe","samples":["Todos los seres humanos nacen libres e iguales en dignidad y derechos y, dotados como están de razón y conciencia, deben comportarse fraternalmente los unos con los otros.","Todo individuo tiene derecho a la vida, a la libertad y a la seguridad de su persona.","Nadie podrá ser arbitrariamente detenido, preso ni desterrado."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_spa.xml","speakers":"https://en.wikipedia.org/wiki/Spanish_language","glottolog":"https://glottolog.org/resource/languoid/id/stan1288"}},{"name":"Portuguese","aka":["Português"],"family":"Indo-European","branch":"Romance","script":"Latin","lat":39.91,"lon":-8.1,"speakers":250000000,"region":"Europe","samples":["Todos os seres humanos nascem livres e iguais em dignidade e em direitos. Dotados de razão e de consciência, devem agir uns para com os outros em espírito de fraternidade.","Todo o indivíduo tem direito à vida, à liberdade e à segurança pessoal.","Ninguém pode ser arbitrariamente preso, detido ou exilado."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_por_PT.xml","speakers":"https://en.wikipedia.org/wiki/Portuguese_language","glottolog":"https://glottolog.org/resource/languoid/id/port1283"}},{"name":"Italian","aka":["Italiano"],"family":"Indo-European","branch":"Romance","script":"Latin","lat":43.0464,"lon":12.6489,"speakers":65000000,"region":"Europe","samples":["Tutti gli esseri umani nascono liberi ed eguali in dignità e diritti. Essi sono dotati di ragione e di coscienza e devono agire gli uni verso gli altri in spirito di fratellanza.","Ogni individuo ha diritto alla vita, alla libertà ed alla sicurezza della propria persona.","Nessun individuo potrà essere arbitrariamente arrestato, detenuto o esiliato."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_ita.xml","speakers":"https://en.wikipedia.org/wiki/Italian_language","glottolog":"https://glottolog.org/resource/languoid/id/ital1282"}},{"name":"German","aka":["Deutsch"],"family":"Indo-European","branch":"Germanic","script":"Latin","lat":48.649,"lon":12.4676,"speakers":95000000,"region":"Europe","samples":["Alle Menschen sind frei und gleich an Würde und Rechten geboren. Sie sind mit Vernunft und Gewissen begabt und sollen einander im Geist der Brüderlichkeit begegnen.","Jeder hat das Recht auf Leben, Freiheit und Sicherheit der Person.","Jeder hat das Recht, überall als rechtsfähig anerkannt zu werden."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_deu_1996.xml","speakers":"https://en.wikipedia.org/wiki/German_language","glottolog":"https://glottolog.org/resource/languoid/id/stan1295"}},{"name":"Dutch","aka":["Nederlands"],"family":"Indo-European","branch":"Germanic","script":"Latin","lat":52.0,"lon":5.0,"speakers":25000000,"region":"Europe","samples":["Alle mensen worden vrij en gelijk in waardigheid en rechten geboren. Zij zijn begiftigd met verstand en geweten, en behoren zich jegens elkander in een geest van broederschap te gedragen.","Een ieder heeft het recht op leven, vrijheid en onschendbaarheid van zijn persoon.","Niemand zal onderworpen worden aan willekeurige arrestatie, detentie of verbanning."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_nld.xml","speakers":"https://en.wikipedia.org/wiki/Dutch_language","glottolog":"https://glottolog.org/resource/languoid/id/dutc1256"}},{"name":"Swedish","aka":["Svenska"],"family":"Indo-European","branch":"Germanic","script":"Latin","lat":59.8006,"lon":17.3895,"speakers":10000000,"region":"Europe","samples":["Alla människor äro födda fria och lika i värde och rättigheter. De äro utrustade med förnuft och samvete och böra handla gentemot varandra i en anda av broderskap.","Envar har rätt till liv, frihet och personlig säkerhet.","Ingen må godtyckligt anhållas, fängslas eller landsförvisas."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_swe.xml","speakers":"https://en.wikipedia.org/wiki/Swedish_language","glottolog":"https://glottolog.org/resource/languoid/id/swed1254"}},{"name":"Danish","aka":["Dansk"],"family":"Indo-European","branch":"Germanic","script":"Latin","lat":54.8655,"lon":9.3628,"speakers":5500000,"region":"Europe","samples":["Alle mennesker er født frie og lige i værdighed og rettigheder. De er udstyret med fornuft og samvittighed, og de bør handle mod hverandre i en broderskabets ånd.","Enhver har ret til liv, frihed og personlig sikkerhed.","Ethvert menneske har overalt i verden ret til at blive anerkendt som retssubjekt."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_dan.xml","speakers":"https://en.wikipedia.org/wiki/Danish_language","glottolog":"https://glottolog.org/resource/languoid/id/dani1285"}},{"name":"Norwegian","aka":["Norsk","Bokmål"],"family":"Indo-European","branch":"Germanic","script":"Latin","lat":61.112,"lon":8.886,"speakers":4320000,"region":"Europe","samples":["Alle mennesker er født frie og med samme menneskeverd og menneskerettigheter. De er utstyrt med fornuft og samvittighet og bør handle mot hverandre i brorskapets ånd.","Enhver har rett til liv, frihet og personlig sikkerhet.","Ethvert menneske har krav på overalt å bli anerkjent som rettssubjekt."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_nob.xml","speakers":"https://en.wikipedia.org/wiki/Norwegian_language","glottolog":"https://glottolog.org/resource/languoid/id/norw1259"}},{"name":"Icelandic","aka":["Íslenska"],"family":"Indo-European","branch":"Germanic","script":"Latin","lat":63.4837,"lon":-19.0212,"speakers":390000,"region":"Europe","samples":["Hver maður er borinn frjáls og jafn öðrum að virðingu og réttindum. Menn eru gæddir vitsmunum og samvizku, og ber þeim að breyta bróðurlega hverjum við annan.","Allir menn eiga rétt til lífs, frelsis og mannhelgi.","Allir menn skulu, hvar í heimi sem er, eiga kröfu á að vera viðurkenndir aðilar að lögum."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_isl.xml","speakers":"https://en.wikipedia.org/wiki/Icelandic_language","glottolog":"https://glottolog.org/resource/languoid/id/icel1247"}},{"name":"Faroese","aka":["Føroyskt"],"family":"Indo-European","branch":"Germanic","script":"Latin","lat":62.0732,"lon":-6.885,"speakers":69000,"region":"Europe","samples":["Øll menniskju eru fødd fræls og jøvn til virðingar og mannarættindi. Tey hava skil og samvitsku og eiga at fara hvørt um annað í bróðuranda.","Ein og hvør hevur rætt til lív, frælsi og persónliga trygd.","Eingin skal verða tilvildarliga handtikin, settur í varðhald ella gjørdur útlagin."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_fao.xml","speakers":"https://en.wikipedia.org/wiki/Faroese_language","glottolog":"https://glottolog.org/resource/languoid/id/faro1244"}},{"name":"Finnish","aka":["Suomi"],"family":"Uralic","branch":"Finnic","script":"Latin","lat":64.7628,"lon":25.5577,"speakers":5000000,"region":"Europe","samples":["Kaikki ihmiset syntyvät vapaina ja tasavertaisina arvoltaan ja oikeuksiltaan. Heille on annettu järki ja omatunto, ja heidän on toimittava toisiaan kohtaan veljeyden hengessä.","Kullakin yksilöllä on oikeus elämään, vapauteen ja henkilökohtaiseen turvallisuuteen.","Ketään ei saa mielivaltaisesti pidättää, vangita tai ajaa maanpakoon."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_fin.xml","speakers":"https://en.wikipedia.org/wiki/Finnish_language","glottolog":"https://glottolog.org/resource/languoid/id/finn1318"}},{"name":"Estonian","aka":["Eesti"],"family":"Uralic","branch":"Finnic","script":"Latin","lat":58.55,"lon":25.82,"speakers":1200000,"region":"Europe","samples":["Kõik inimesed sünnivad vabadena ja võrdsetena oma väärikuselt ja õigustelt. Neile on antud mõistus ja südametunnistus ja nende suhtumist üksteisesse peab kandma vendluse vaim.","Igal inimesel on õigus elule, vabadusele ja isikupuutumatusele.","Kedagi ei või meelevaldselt vahistada, kinni pidada või pagendada."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_est.xml","speakers":"https://en.wikipedia.org/wiki/Estonian_language","glottolog":"https://glottolog.org/resource/languoid/id/esto1258"}},{"name":"Hungarian","aka":["Magyar"],"family":"Uralic","branch":"Hungaric","script":"Latin","lat":46.9069,"lon":19.6555,"speakers":12000000,"region":"Europe","samples":["Minden. emberi lény szabadon születik és egyenlő méltósága és joga van. Az emberek, ésszel és lelkiismerettel bírván, egymással szemben testvéri szellemben kell hogy viseltessenek.","Minden személynek joga van az élethez, a szabadsághoz és a személyi biztonsághoz.","Mindenkinek joga van ahhoz, hogy jogalanyiságát bárhol elismerjék."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_hun.xml","speakers":"https://en.wikipedia.org/wiki/Hungarian_language","glottolog":"https://glottolog.org/resource/languoid/id/hung1274"}},{"name":"Polish","aka":["Polski"],"family":"Indo-European","branch":"Slavic","script":"Latin","lat":51.8439,"lon":18.6255,"speakers":40000000,"region":"Europe","samples":["Wszyscy ludzie rodzą się wolni i równi pod względem swej godności i swych praw. Są oni obdarzeni rozumem i sumieniem i powinni postępować wobec innych w duchu braterstwa.","Każdy człowiek ma prawo do życia, wolności i bezpieczeństwa swej osoby.","Nikogo nie wolno samowolnie aresztować, zatrzymać lub wygnać z kraju."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_pol.xml","speakers":"https://en.wikipedia.org/wiki/Polish_language","glottolog":"https://glottolog.org/resource/languoid/id/poli1260"}},{"name":"Czech","aka":["Čeština"],"family":"Indo-European","branch":"Slavic","script":"Latin","lat":49.8734,"lon":15.1044,"speakers":9800000,"region":"Europe","samples":["Všichni lidé rodí se svobodní a sobě rovní co do důstojnosti a práv. Jsou nadáni rozumem a svědomím a mají spolu jednat v duchu bratrství.","Každý má právo na život, svobodu a osobní bezpečnost.","Každý má právo na to, aby byla všude uznávána jeho právní osobnost."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_ces.xml","speakers":"https://en.wikipedia.org/wiki/Czech_language","glottolog":"https://glottolog.org/resource/languoid/id/czec1258"}},{"name":"Slovak","aka":["Slovenčina"],"family":"Indo-European","branch":"Slavic","script":"Latin","lat":48.5457,"lon":18.7848,"speakers":5000000,"region":"Europe","samples":["Všetci ľudia sa rodia slobodní a sebe rovní , čo sa týka ich dostojnosti a práv. Sú obdarení rozumom a majú navzájom jednať v bratskom duchu.","Každý má právo na život, slobodu a osobnú bezpečnosť.","Každý má právo, aby bola všade uznávaná jeho právna osobnosť."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_slk.xml","speakers":"https://en.wikipedia.org/wiki/Slovak_language","glottolog":"https://glottolog.org/resource/languoid/id/slov1269"}},{"name":"Slovenian","aka":["Slovene","Slovenščina"],"family":"Indo-European","branch":"Slavic","script":"Latin","lat":46.2543,"lon":14.7766,"speakers":2500000,"region":"Europe","samples":["Vsi ljudje se rodijo svobodni in imajo enako dostojanstvo in enake pravice. Obdarjeni so z razumom in vestjo in bi morali ravnati drug z drugim kakor bratje.","Vsakdo ima pravico do življenja, do prostosti in do osebne varnosti.","Nihče ne sme biti samovoljno zaprt, pridržan ali izgnan."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_slv.xml","speakers":"https://en.wikipedia.org/wiki/Slovene_language","glottolog":"https://glottolog.org/resource/languoid/id/slov1268"}},{"name":"Croatian","aka":["Hrvatski"],"family":"Indo-European","branch":"Slavic","script":"Latin","lat":45.555,"lon":15.982,"speakers":5100000,"region":"Europe","samples":["Sva ljudska bića rađaju se slobodna i jednaka u dostojanstvu i pravima. Ona su obdarena razumom i sviješću i treba da jedno prema drugome postupaju u duhu bratstva.","Svatko ima pravo na život, slobodu i osobnu sigurnost.","Svatko ima pravo da se svagdje pred zakonom priznaje kao osoba."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_hrv.xml","speakers":"https://en.wikipedia.org/wiki/Croatian_language","glottolog":"https://glottolog.org/resource/languoid/id/croa1245"}},{"name":"Serbian","aka":["Српски"],"family":"Indo-European","branch":"Slavic","script":"Cyrillic","lat":44.3238,"lon":21.9192,"speakers":8200000,"region":"Europe","samples":["Сва људска бића рађају се слободна и једнака у достојанству и правима. Она су обдарена разумом и свешћу и треба једни према другима да поступају у духу братства.","Свако има право на живот, слободу и безбедност личности.","Свако има право да свуда буде признат као правни субјект."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_srp_cyrl.xml","speakers":"https://en.wikipedia.org/wiki/Serbian_language","glottolog":"https://glottolog.org/resource/languoid/id/serb1264"}},{"name":"Bosnian","aka":["Bosanski"],"family":"Indo-European","branch":"Slavic","script":"Latin","lat":43.859,"lon":17.046,"speakers":3100000,"region":"Europe","samples":["Sva ljudska bića rađaju se slobodna i jednaka u dostojanstvu i pravima. Ona su obdarena razumom i sviješću i treba da jedno prema drugome postupaju u duhu bratstva.","Svako ima pravo na život, slobodu i osobnu sigurnost.","Svako ima pravo da se svagdje pred zakonom priznaje kao osoba."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_bos_latn.xml","speakers":"https://en.wikipedia.org/wiki/Bosnian_language","glottolog":"https://glottolog.org/resource/languoid/id/bosn1245"}},{"name":"Macedonian","aka":["Македонски"],"family":"Indo-European","branch":"Slavic","script":"Cyrillic","lat":41.5957,"lon":21.7932,"speakers":1700000,"region":"Europe","samples":["Сите човечки суштества се раѓаат слободни и еднакви по достоинство и права. Тие се обдарени со разум и совест и треба да се однесуваат еден кон друг во духот на општо човечката припадност.","Секој има право на живот, слобода и сигурност.","Секој има право насекаде да биде признаен како личност пред законот."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_mkd.xml","speakers":"https://en.wikipedia.org/wiki/Macedonian_language","glottolog":"https://glottolog.org/resource/languoid/id/mace1250"}},{"name":"Bulgarian","aka":["Български"],"family":"Indo-European","branch":"Slavic","script":"Cyrillic","lat":43.3646,"lon":25.047,"speakers":6800000,"region":"Europe","samples":["Всички хора се раждат свободни и равни по достойнство и права. Те са надарени с разум и съвест и следва да се отнасят помежду си в дух на братство.","Всеки има право на живот, свобода и лична сигурност.","Никой не трябва да бъде подлаган на произволен арест, задържане или изгнание."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_bul.xml","speakers":"https://en.wikipedia.org/wiki/Bulgarian_language","glottolog":"https://glottolog.org/resource/languoid/id/bulg1262"}},{"name":"Russian","aka":["Русский"],"family":"Indo-European","branch":"Slavic","script":"Cyrillic","lat":59.0,"lon":50.0,"speakers":145000000,"region":"Europe","samples":["Все люди рождаются свободными и равными в своем достоинстве и правах. Они наделены разумом и совестью и должны поступать в отношении друг друга в духе братства.","Каждый человек имеет право на жизнь, на свободу и на личную неприкосновенность.","Никто не может быть подвергнут произвольному аресту, задержанию или изгнанию."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_rus.xml","speakers":"https://en.wikipedia.org/wiki/Russian_language","glottolog":"https://glottolog.org/resource/languoid/id/russ1263"}},{"name":"Ukrainian","aka":["Українська"],"family":"Indo-European","branch":"Slavic","script":"Cyrillic","lat":49.796,"lon":29.945,"speakers":32000000,"region":"Europe","samples":["Всі люди народжуються вільними і рівними у своїй гідності та правах. Вони наділені розумом і совістю і повинні діяти у відношенні один до одного в дусі братерства.","Кожна людина має право на життя, на свободу і на особисту недоторканність.","Ніхто не може зазнавати безпідставного арешту, затримання або вигнання."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_ukr.xml","speakers":"https://en.wikipedia.org/wiki/Ukrainian_language","glottolog":"https://glottolog.org/resource/languoid/id/ukra1253"}},{"name":"Belarusian","aka":["Беларуская"],"family":"Indo-European","branch":"Slavic","script":"Cyrillic","lat":53.2307,"lon":25.6038,"speakers":5094000,"region":"Europe","samples":["Усе людзі нараджаюцца свабоднымі і роўнымі ў сваёй годнасці і правах. Яны надзелены розумам і сумленнем і павінны ставіцца адзін да аднаго ў духу брацтва.","Кожны чалавека мае права на жыццё, на свабоду і на асабістую недатыкальнасць.","Ні над кім не павінны ўчыняцца самавольны арышт, затрыманне або выгнанне."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_bel.xml","speakers":"https://en.wikipedia.org/wiki/Belarusian_language","glottolog":"https://glottolog.org/resource/languoid/id/bela1254"}},{"name":"Lithuanian","aka":["Lietuvių"],"family":"Indo-European","branch":"Baltic","script":"Latin","lat":55.1429,"lon":23.9601,"speakers":4000000,"region":"Europe","samples":["Visi žmonės gimsta laisvi ir lygūs savo orumu ir teisėmis. Jiems suteiktas protas ir sąžinė ir jie turi elgtis vienas kito atžvilgiu kaip broliai.","Kiekvienas žmogus turi teisę į gyvybę, laisvę ir asmens neliečiamybę.","Niekas negali būti savavališkai areštuotas, suimtas ar ištremtas."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_lit.xml","speakers":"https://en.wikipedia.org/wiki/Lithuanian_language","glottolog":"https://glottolog.org/resource/languoid/id/lith1251"}},{"name":"Latvian","aka":["Latviešu"],"family":"Indo-European","branch":"Baltic","script":"Latin","lat":57.0,"lon":24.0,"speakers":1500000,"region":"Europe","samples":["Visi cilvēki piedzimst brīvi un vienlīdzīgi savā pašcieņā un tiesībās. Viņi ir apveltīti ar saprātu un sirdsapziņu, un viņiem jāizturas citam pret citu brālības garā.","Ikvienam ir tiesības uz dzīvību, brīvību un personas neaizskaramību.","Ikvienam, visur, ir tiesības būt atzītam par personu likuma priekšā."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_lav.xml","speakers":"https://en.wikipedia.org/wiki/Latvian_language","glottolog":"https://glottolog.org/resource/languoid/id/stan1325"}},{"name":"Romanian","aka":["Română"],"family":"Indo-European","branch":"Romance","script":"Latin","lat":46.3913,"lon":24.2256,"speakers":22000000,"region":"Europe","samples":["Toate ființele umane se nasc libere și egale în demnitate și în drepturi. Ele sunt înzestrate cu rațiune și conștiință și trebuie să se comporte unele față de altele în spiritul fraternității.","Orice ființă umană are dreptul la viață, la libertate și la securitatea persoanei sale.","Nimeni nu trebuie să fie arestat, deținut sau exilat în mod arbitrar."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_ron_2006.xml","speakers":"https://en.wikipedia.org/wiki/Romanian_language","glottolog":"https://glottolog.org/resource/languoid/id/roma1327"}},{"name":"Greek","aka":["Ελληνικά"],"family":"Indo-European","branch":"Greek","script":"Greek","lat":38.36,"lon":23.13,"speakers":13500000,"region":"Europe","samples":["Όλοι οι άνθρωποι γεννιούνται ελεύθεροι και ίσοι στην αξιοπρέπεια και τα δικαιώματα. Είναι προικισμένοι με λογική και συνείδηση, και οφείλουν να συμπεριφέρονται μεταξύ τους με πνεύμα αδελφοσύνης.","Κάθε άτομο έχει δικαίωμα στη ζωή, την ελευθερία και την προσωπική του ασφάλεια.","Κανείς δεν μπορεί να συλλαμβάνεται, να κρατείται ή να εξορίζεται αυθαίρετα."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_ell_monotonic.xml","speakers":"https://en.wikipedia.org/wiki/Greek_language","glottolog":"https://glottolog.org/resource/languoid/id/mode1248"}},{"name":"Albanian","aka":["Shqip"],"family":"Indo-European","branch":"Albanian","script":"Latin","lat":41.0,"lon":20.0,"speakers":7500000,"region":"Europe","samples":["Të gjithë njerëzit lindin të lirë dhe të barabartë në dinjitet dhe në të drejta. Ata kanë arsye dhe ndërgjegje dhe duhet të sillen ndaj njëri tjetrit me frymë vëllazërimi.","Gjithkush ka të drejtë të jetojë, të jetë i lirë dhe të ketë sigurimin vetjak.","Gjithkush ka të drejtë që t'i njihet kudo personaliteti juridik."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_als.xml","speakers":"https://en.wikipedia.org/wiki/Albanian_language","glottolog":"https://glottolog.org/resource/languoid/id/tosk1239"}},{"name":"Irish","aka":["Gaeilge","Irish Gaelic"],"family":"Indo-European","branch":"Celtic","script":"Latin","lat":53.2186,"lon":-7.6151,"speakers":null,"region":"Europe","samples":["Saoláitear na daoine uile saor agus comhionann ina ndínit agus ina gcearta. Tá bauidh an réasúin agus an choinsiasa acu agus dlíd iad féin d'iompar de mheon bhrthreachais i leith a chéile.","Tá ag gach uile dhuine, an ceart chun marthana, chun saoirse agus chun slándála a phearsan.","Ní déanfar go forlamhach aon duine a ghabháil a choinneáil ná a chur ar deoraíocht."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_gle.xml","speakers":"https://en.wikipedia.org/wiki/Irish_language","glottolog":"https://glottolog.org/resource/languoid/id/iris1253"}},{"name":"Scottish Gaelic","aka":["Gàidhlig"],"family":"Indo-European","branch":"Celtic","script":"Latin","lat":56.7574,"lon":-5.2437,"speakers":70000,"region":"Europe","samples":["Tha gach uile dhuine air a bhreth saor agus co-ionnan ann an urram 's ann an còirichean. Tha iad air am breth le reusan is le cogais agus mar sin bu chòir dhaibh a bhith beò nam measg fhein ann an spiorad bràthaireil,","Tha còir aig gach neach air beatha, saorsa agus tearainteachd.","Cha bhi neach air a chur an sàs neo ann an grèim neo air fhògarrachadh gu mi-laghail."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_gla.xml","speakers":"https://en.wikipedia.org/wiki/Scottish_Gaelic","glottolog":"https://glottolog.org/resource/languoid/id/scot1245"}},{"name":"Welsh","aka":["Cymraeg"],"family":"Indo-European","branch":"Celtic","script":"Latin","lat":52.0,"lon":-4.0,"speakers":538300,"region":"Europe","samples":["Genir pawb yn rhydd ac yn gydradd â’i gilydd mewn urddas a hawliau. Fe’u cynysgaeddir â rheswm a chydwybod, a dylai pawb ymddwyn y naill at y llall mewn ysbryd cymodlon.","Y mae gan bawb hawl i fywyd, rhyddid a diogelwch.","Ni ddylai neb gael eu dwyn i ddalfa, na’u caethiwo na’u halltudio yn fympwyol."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_cym.xml","speakers":"https://en.wikipedia.org/wiki/Welsh_language","glottolog":"https://glottolog.org/resource/languoid/id/wels1247"}},{"name":"Breton","aka":["Brezhoneg"],"family":"Indo-European","branch":"Celtic","script":"Latin","lat":48.2452,"lon":-3.7893,"speakers":107000,"region":"Europe","samples":["Dieub ha par en o dellezegezh hag o gwirioù eo ganet an holl dud. Poell ha skiant zo dezho ha dleout a reont bevañ an eil gant egile en ur spered a genvreudeuriezh.","Gwir a zo gant pep hini d’ar vuhez, d’ar frankiz, ha d’an diogelroez evitañ.","Den ebet ne vo harzet, bac’het pe harluet diouzh c’hoant."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_bre.xml","speakers":"https://en.wikipedia.org/wiki/Breton_language","glottolog":"https://glottolog.org/resource/languoid/id/bret1244"}},{"name":"Basque","aka":["Euskara"],"family":"Basque (isolate)","branch":null,"script":"Latin","lat":43.2787,"lon":-1.3162,"speakers":806000,"region":"Europe","samples":["Gizon-emakume guztiak aske jaiotzen dira, duintasun eta eskubide berberak dituztela; eta ezaguera eta kontzientzia dutenez gero, elkarren artean senide legez jokatu beharra dute.","Norbanako guztiek dute bizitzeko, aske izateko eta segurtasunerako eskubidea.","Inor ezingo da arrazoirik gabe atxilotu, preso hartu edo erbesteratu."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_eus.xml","speakers":"https://en.wikipedia.org/wiki/Basque_language","glottolog":"https://glottolog.org/resource/languoid/id/basq1248"}},{"name":"Catalan","aka":["Català","Valencian"],"family":"Indo-European","branch":"Romance","script":"Latin","lat":41.453,"lon":1.569,"speakers":4100000,"region":"Europe","samples":["Tots els éssers humans neixen lliures i iguals en dignitat i en drets. Són dotats de raó i de consciència, i han de comportar-se fraternalment els uns amb els altres.","Tota persona té dret a la vida, a la llibertat i a la seva seguretat.","Ningú no serà detingut, pres o desterrat arbitràriament."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_cat.xml","speakers":"https://en.wikipedia.org/wiki/Catalan_language","glottolog":"https://glottolog.org/resource/languoid/id/stan1289"}},{"name":"Galician","aka":["Galego"],"family":"Indo-European","branch":"Romance","script":"Latin","lat":42.2446,"lon":-7.5343,"speakers":2400000,"region":"Europe","samples":["Tódolos seres humanos nacen libres e iguais en dignidade e dereitos e, dotados como están de razón e conciencia, díbense comportar fraternalmente uns cos outros.","Todo individuo ten dereito á vida, á liberdade e á seguridade da súa persoa.","Ninguín poderá ser arbitrariamente detido, preso nin desterrado."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_glg.xml","speakers":"https://en.wikipedia.org/wiki/Galician_language","glottolog":"https://glottolog.org/resource/languoid/id/gali1258"}},{"name":"Maltese","aka":["Malti"],"family":"Afro-Asiatic","branch":"Semitic","script":"Latin","lat":35.8884,"lon":14.4508,"speakers":570000,"region":"Europe","samples":["Il-bnedmin kollha jitwieldu ħielsa u ugwali fid-dinjità u d-drittijiet. Huma mogħnija bir-raġuni u bil-kuxjenza u għandhom iġibu ruħhom ma’ xulxin bi spirtu ta’ aħwa.","Kull bniedem għandu l-jedd għall-ħajja, għall-ħelsien u għas-sigurtà tal-persuna tiegħu.","Kulħadd għandu l-jedd li jintgħaraf kullimkien bħala persuna quddiem il-liġi."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_mlt.xml","speakers":"https://en.wikipedia.org/wiki/Maltese_language","glottolog":"https://glottolog.org/resource/languoid/id/malt1254"}},{"name":"Luxembourgish","aka":["Lëtzebuergesch"],"family":"Indo-European","branch":"Germanic","script":"Latin","lat":49.6839,"lon":6.1493,"speakers":400000,"region":"Europe","samples":["All Mënsch kënnt fräi a mat deer selwechter Dignitéit an dene selwechte Rechter op d'Welt. Jiddereen huet säi Verstand a säi Gewësse krut an soll an engem Geescht vu Bridderlechkeet denen anere géintiwwer handelen.","All Mësch huet Recht op d'Liewen, op d'Fräiheet an op d'Secherheet vu sénger Persoun.","Kee Mënsch duerf arbiträr verhaft, agesat odder ausgewise gin."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_ltz.xml","speakers":"https://en.wikipedia.org/wiki/Luxembourgish","glottolog":"https://glottolog.org/resource/languoid/id/luxe1241"}},{"name":"Romansh","aka":["Rumantsch"],"family":"Indo-European","branch":"Romance","script":"Latin","lat":46.5538,"lon":9.9281,"speakers":40000,"region":"Europe","samples":["Tut ils umans naschan libers ed eguals en dignitad ed en dretgs. Els èn dotads cun raschun e conscienza e duain agir in vers l’auter en spiert da fraternitad.","Mintga uman ha il dretg da vita, da libertad e da segirtad da la persuna.","Nagin na dastga vegnir arrestà, detegnì u exilià arbitrariamain."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_roh_rumgr.xml","speakers":"https://en.wikipedia.org/wiki/Romansh_language","glottolog":"https://glottolog.org/resource/languoid/id/roma1326"}},{"name":"West Frisian","aka":["Frisian","Frysk"],"family":"Indo-European","branch":"Germanic","script":"Latin","lat":53.143,"lon":5.8609,"speakers":470000,"region":"Europe","samples":["Alle minsken wurde frij en gelyk yn weardigens en rjochten berne. Hja hawwe ferstân en gewisse meikrigen en hearre har foar inoar oer yn in geast fan bruorskip te hâlden en te dragen.","Elk hat rjocht op libben, frijheid en ûnskeinberens fan syn persoan.","Elk hat, wêr't er ek is, it rjocht om as persoan erkend te wurden foar de wet."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_fri.xml","speakers":"https://en.wikipedia.org/wiki/West_Frisian_language","glottolog":"https://glottolog.org/resource/languoid/id/west2354"}},{"name":"Occitan","aka":["Occitan","Provençal"],"family":"Indo-European","branch":"Romance","script":"Latin","lat":44.1415,"lon":6.8298,"speakers":200000,"region":"Europe","samples":["Tóuti lis uman naisson libre. Soun egau pèrla digneta e li dre. An tóuti uno resoun e uno counsciènci. Se dèvon tenifreirenau lis un 'mé lis autre.","Cado persouno a dre à la vido, à la liberta,e à la segureta.","Degun sara arresta, embarra vo eisila pèrarbitràri."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_prv.xml","speakers":"https://en.wikipedia.org/wiki/Occitan_language","glottolog":"https://glottolog.org/resource/languoid/id/occi1239"}},{"name":"Northern Sami","aka":["Sami","Davvisámegiella"],"family":"Uralic","branch":"Saami","script":"Latin","lat":68.725,"lon":22.1113,"speakers":25000,"region":"Europe","samples":["Buot olbmot leat riegádan friddjan ja olmmošárvvu ja olmmošvuoigatvuođaid dáfus. Sii leat jierbmalaš olbmot geain lea oamedovdu ja sii gálggaše leat dego vieljačagat.","Juohke olbmos lea vuoigatvuohta eallimii, friddjavuhtii ja persovnnalaš oadjebasvuhtii.","Juohke olbmos lea juohke sajis vuoigatvuohta dasa, ahte son galgá dovddastuvvot olmmošoktagassan lága ovddas."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_sme.xml","speakers":"https://en.wikipedia.org/wiki/Northern_S%C3%A1mi","glottolog":"https://glottolog.org/resource/languoid/id/nort2671"}},{"name":"Yiddish","aka":["ייִדיש"],"family":"Indo-European","branch":"Germanic","script":"Hebrew","lat":51.75,"lon":19.42,"speakers":600000,"region":"Europe","samples":["יעדער מענטש װערט געבױרן פֿרײַ און גלײַך אין כּבֿוד און רעכט. יעדער װערט באַשאָנקן מיט פֿאַרשטאַנד און געװיסן; יעדער זאָל זיך פֿירן מיט אַ צװײטן אין אַ געמיט פֿון ברודערשאַפֿט.","יעדער האָט רעכט אױף לעבן, פֿרײַהײט, און פּערזענלעכער פֿאַרזיכערונג.","יעדער האָט אומעטום דאָס רעכט אױף דעם, מען זאָל אים אָנערקענען װי אַ מענטש לױטן געזעץ."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_ydd.xml","speakers":"https://en.wikipedia.org/wiki/Yiddish","glottolog":"https://glottolog.org/resource/languoid/id/east2295"}},{"name":"Georgian","aka":["ქართული","Kartuli"],"family":"Kartvelian","branch":"Georgian-Zan","script":"Georgian","lat":41.8504,"lon":43.7861,"speakers":3760000,"region":"Asia","samples":["ყოველი ადამიანი იბადება თავისუფალი და თანასწორი თავისი ღირსებითა და უფლებებით. მათ მინიჭებული აქვთ გონება და სინდისი და ერთმანეთის მიმართ უნდა ექცეოდნენ ძმობის სულისკვეთებით.","ყოველ ადამიანს აქვს სიცოცხლის, თავისუფლებისა და პირადი ხელშეუხებლობის უფლება.","არავინ შეიძლება დაექვემდებაროს თვითნებურ დაკავებას, დაპატიმრებას ან გაძევებას."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_kat.xml","speakers":"https://en.wikipedia.org/wiki/Georgian_language","glottolog":"https://glottolog.org/resource/languoid/id/nucl1302"}},{"name":"Armenian","aka":["Հայերեն","Hayeren"],"family":"Indo-European","branch":"Armenic","script":"Armenian","lat":40.0,"lon":45.0,"speakers":5300000,"region":"Asia","samples":["Բոլոր մարդիկ ծնվում են ազատ ու հավասար իրենց արժանապատվությամբ ու իրավունքներով։ Նրանք ունեն բանականություն ու խիղճ և միմյանց պետք է եղբայրաբար վերաբերվեն։","Յուրաքանչյուր ոք ունի ապրելու, ազատության ու անձի անձեռնմխելիության իրավունք։","Ամեն ոք, ուր էլ որ լինի, իրավունք ունի ճանաչվել որպես իրավասուբյեկտ։"],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_hye.xml","speakers":"https://en.wikipedia.org/wiki/Armenian_language","glottolog":"https://glottolog.org/resource/languoid/id/nucl1235"}},{"name":"Azerbaijani","aka":["Azeri","Azərbaycan dili"],"family":"Turkic","branch":"Oghuz","script":"Latin","lat":40.9777,"lon":46.4737,"speakers":24000000,"region":"Asia","samples":["Bütün insanlar ləyaqət və hüquqlarına görə azad və bərabər doğulurlar. Onların şüurları və vicdanları var və bir-birlərinə münasibətdə qardaşlıq ruhunda davranmalıdırlar.","Hər bir şəxsin yaşamaq, azadlıq və şəxsi toxunulmazlıq hüququ var.","Heç kim özbaşına həbsə, tutulmaya və ya sürgünə məruz qala bilməz."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_azj_latn.xml","speakers":"https://en.wikipedia.org/wiki/Azerbaijani_language","glottolog":"https://glottolog.org/resource/languoid/id/nort2697"}},{"name":"Turkish","aka":["Türkçe"],"family":"Turkic","branch":"Oghuz","script":"Latin","lat":39.8667,"lon":32.8667,"speakers":85000000,"region":"Asia","samples":["Bütün insanlar hür, haysiyet ve haklar bakımından eşit doğarlar. Akıl ve vicdana sahiptirler ve birbirlerine karşı kardeşlik zihniyeti ile hareket etmelidirler.","Yaşamak, hürriyet ve kişi emniyeti her ferdin hakkıdır.","Hiç kimse keyfi olarak tutuklanamaz, alıkonulanamaz veya sürülemez."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_tur.xml","speakers":"https://en.wikipedia.org/wiki/Turkish_language","glottolog":"https://glottolog.org/resource/languoid/id/nucl1301"}},{"name":"Persian","aka":["Farsi","فارسی"],"family":"Indo-European","branch":"Iranian","script":"Arabic","lat":32.9,"lon":53.3,"speakers":91000000,"region":"Asia","samples":["تمام افراد بشر آزاد بدنیا میایند و از لحاظ حیثیت و حقوق با هم برابرند. همه دارای عقل و وجدان میباشند و باید نسبت بیکدیگر با روح برادری رفتار کنند.","هر کس حق زندگی، آزادی و امنیت شخصی دارد.","احدی نمیتواند خودسرانه توقیف ‐ حبس یا تبعید بشود."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_pes_1.xml","speakers":"https://en.wikipedia.org/wiki/Persian_language","glottolog":"https://glottolog.org/resource/languoid/id/west2369"}},{"name":"Kurdish","aka":["Kurmanji","Kurdî"],"family":"Indo-European","branch":"Iranian","script":"Latin","lat":37.0,"lon":43.0,"speakers":17000000,"region":"Asia","samples":["Hemû mirov azad û di weqar û mafan de wekhev tên dinyayê. Ew xwedî hiş û şuûr in û divê li hember hev bi zihniyeteke bratiyê bilivin.","Herkes xwedî mafê jiyan, azadî û ewleyiya şexsê xwe ye.","Tukes nikare bi awayekî kêfî bê girtin, hebs an sirgûn kirin."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_kmr.xml","speakers":"https://en.wikipedia.org/wiki/Kurmanji","glottolog":"https://glottolog.org/resource/languoid/id/nort2641"}},{"name":"Arabic","aka":["العربية","Standard Arabic"],"family":"Afro-Asiatic","branch":"Semitic","script":"Arabic","lat":27.9625,"lon":43.8525,"speakers":411000000,"region":"Asia","samples":["يولد جميع الناس أحرارًا متساوين في الكرامة والحقوق. وقد وهبوا عقلاً وضميرًا وعليهم أن يعامل بعضهم بعضًا بروح الإخاء.","لكل فرد الحق في الحياة والحرية وسلامة شخصه.","لا يجوز القبض على أي إنسان أو حجزه أو نفيه تعسفاً."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_arb.xml","speakers":"https://en.wikipedia.org/wiki/Arabic","glottolog":"https://glottolog.org/resource/languoid/id/stan1318"}},{"name":"Hebrew","aka":["עברית"],"family":"Afro-Asiatic","branch":"Semitic","script":"Hebrew","lat":31.1056,"lon":35.0179,"speakers":5000000,"region":"Asia","samples":["כל בני אדם נולדו בני חורין ושווים בערכם ובזכויותיהם. כולם חוננו בתבונה ובמצפון, לפיכך חובה עליהם לנהוג איש ברעהו ברוח של אחוה.","כל אדם יש לו הזכות לחיים, לחרות ולבטחון אישי.","לא ייאסר אדם, לא ייעצר ולא יוגלה באופן שרירותי."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_heb.xml","speakers":"https://en.wikipedia.org/wiki/Hebrew_language","glottolog":"https://glottolog.org/resource/languoid/id/hebr1245"}},{"name":"Abkhaz","aka":["Abkhazian","Аҧсуа"],"family":"Abkhaz-Adyge","branch":"Abkhaz-Abaza","script":"Cyrillic","lat":43.0562,"lon":41.1591,"speakers":190000,"region":"Europe","samples":["Дарбанзаалак ауаҩы дшоуп ихы дақәиҭны. Ауаа зегь зинлеи патулеи еиҟароуп. Урҭ ирымоуп ахшыҩи аламыси, дара дарагь аешьеи аешьеи реиҧш еизыҟазароуп.","Дарбанзаалак ауаҩы аҧсҭазаареи, ахақәиҭреи, хаҭала аӡә диламкьысуа аҟазаареи рзин имоуп.","Дарбанзаалак ауаҩы хаҳәатәыла ирбаандаҩтәра, иаанкылара, мамзаргьы иқәцара ҟалом."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_abk.xml","speakers":"https://en.wikipedia.org/wiki/Abkhaz_language","glottolog":"https://glottolog.org/resource/languoid/id/abkh1244"}},{"name":"Pashto","aka":["پښتو"],"family":"Indo-European","branch":"Iranian","script":"Arabic","lat":34.0,"lon":71.33,"speakers":51000000,"region":"Asia","samples":["د بشر ټول افراد ازاد نړۍ ته راځي او د حيثيت او د حقوقو له پلوه سره برابر دي۔ ټول د عقل او وجدان خاوندان دي او بايد يو له بل سره د ورورۍ په روحيه سره چلنند کړي۔","هر څوک د ژوند، ازادې او شخصي امنيت حق لري۔","هيڅ څوک بايد په خپل سر توقيف، حبس او يا تبعيد نه شي۔"],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_pbu.xml","speakers":"https://en.wikipedia.org/wiki/Pashto","glottolog":"https://glottolog.org/resource/languoid/id/nort2646"}},{"name":"Kazakh","aka":["Қазақша"],"family":"Turkic","branch":"Kipchak","script":"Cyrillic","lat":51.17,"lon":71.454,"speakers":16000000,"region":"Asia","samples":["Барлық адамдар тумысынан азат және қадір‐қасиеті мен кұқықтары тең болып дүниеге келеді. Адамдарға ақыл‐парасат, ар‐ождан берілген, сондықтан олар бір‐бірімен туыстық, бауырмалдық қарым‐қатынас жасаулары тиіс.","Әр адам өмір сүруге, бостандықта болуға және оның жеке басына қол сұғылмауына құқылы.","Әр адам қай жерде жүрсе де, құқықтық субъектісі ретінде танылуына құқылы."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_kaz.xml","speakers":"https://en.wikipedia.org/wiki/Kazakh_language","glottolog":"https://glottolog.org/resource/languoid/id/kaza1248"}},{"name":"Uzbek","aka":["Oʻzbekcha"],"family":"Turkic","branch":"Turkestan (Karluk)","script":"Latin","lat":40.886,"lon":69.211,"speakers":36000000,"region":"Asia","samples":["Barcha odamlar erkin, qadr‐qimmat va huquqlarda teng boʻlib tugʻiladilar. Ular aql va vijdon sohibidirlar va bir‐birlariga birodarlarcha muomala qilishlari zarur.","Har bir inson yashash, erkinlik va shaxsiy daxlsizlik huquqiga egadir.","Hech kim oʻzboshimchalik bilan qamalishi, ushlanishi yoki quvgʻin qilinishi mumkin emas."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_uzn_latn.xml","speakers":"https://en.wikipedia.org/wiki/Uzbek_language","glottolog":"https://glottolog.org/resource/languoid/id/nort2690"}},{"name":"Kyrgyz","aka":["Kirghiz","Кыргызча"],"family":"Turkic","branch":"Kipchak","script":"Cyrillic","lat":42.0,"lon":74.0,"speakers":5600000,"region":"Asia","samples":["Бардык адамдар өз беделинде жана укуктарында эркин жана тең укуктуу болуп жаралат. Алардын аң‐сезими менен абийири бар жана бири‐бирине бир туугандык мамилекылууга тийиш.","Ар бир адам жашоого, эркиндикке жана жеке кол тийбестикке укуктуу.","Эч ким ээнбаштык менен камакка алынууга, кармалууга же куугунтукталууга тийиш эмес."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_kir.xml","speakers":"https://en.wikipedia.org/wiki/Kyrgyz_language","glottolog":"https://glottolog.org/resource/languoid/id/kirg1245"}},{"name":"Turkmen","aka":["Türkmençe"],"family":"Turkic","branch":"Oghuz","script":"Latin","lat":37.0872,"lon":59.1757,"speakers":6800000,"region":"Asia","samples":["Adamlaryň hemmesi azat dogulýarlar we öz mertebesi hem‐de hukuklary boýunça ilkibaşdan deňdirler. Olara ozal‐başdan aň, ynsap berlendir we biri‐birine özara doganlyk ruhunda çemeleşmek olaryň ýaraşygydyr.","Her bir adam ýaşaýyşa, azatlyga we şahsy eldegrilmezlige haklydyr.","Her bir adam, nirededigine garamazdan, özüniň hukuk subýekti hökmünde ykrar edilmegine haklydyr."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_tuk_latn.xml","speakers":"https://en.wikipedia.org/wiki/Turkmen_language","glottolog":"https://glottolog.org/resource/languoid/id/turk1304"}},{"name":"Tajik","aka":["Тоҷикӣ"],"family":"Indo-European","branch":"Iranian","script":"Cyrillic","lat":38.8213,"lon":68.5549,"speakers":10500000,"region":"Asia","samples":["Тамоми одамон озод ва аз лиҳози шарафу ҳуқуқ ба ҳам баробар ба дунё меоянд. Онҳо соҳиби ақлу виҷдонанд ва бояд бо якдигар муносибати бародарона дошта бошанд.","Ҳар як инсон ба ҳаёт, озодӣ ва дахлнопазирии шахсӣ ҳақ дорад.","Ҳеҷ касро худсарона дастгир, ҳабс ё бадарға кардан мумкин нест."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_tgk.xml","speakers":"https://en.wikipedia.org/wiki/Tajik_language","glottolog":"https://glottolog.org/resource/languoid/id/taji1245"}},{"name":"Tatar","aka":["Татарча"],"family":"Turkic","branch":"Kipchak","script":"Cyrillic","lat":55.7959,"lon":49.1158,"speakers":4000000,"region":"Europe","samples":["Барлык кешеләр дә азат һәм үз абруйлары һәм хокуклары ягыннан тиң булып туалар. Аларга акыл һәм вөҗдан бирелгән һәм бер-берсенә карата туганнарча мөнәсәбәттә булырга тиешләр.","Һәр кешенең тормышка, иреккә һәм шәхси кагылгысызлыкка хокукы бар.","Беркем дә нигезсез рәвештә кулга алынуга, тоткарлануга, куылуга дучар ителергә тиеш түгел."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_tat.xml","speakers":"https://en.wikipedia.org/wiki/Tatar_language","glottolog":"https://glottolog.org/resource/languoid/id/tata1255"}},{"name":"Yakut","aka":["Sakha","Саха тыла"],"family":"Turkic","branch":"Sakha-Dolgan","script":"Cyrillic","lat":61.6974,"lon":133.9803,"speakers":450000,"region":"Asia","samples":["Дьон барыта бэйэ суолтатыгар уонна быраабыгар тэҥ буолан төрүүллэр. Кинилэр бары өркөн өйдөөх, суобастаах буолан төрүүллэр, уонна бэйэ бэйэлэригэр тылга кииринигэс быһыылара доҕордоһуу тыыннаах буолуохтаах.","Хас биирдии киһи үчүгэй олоҕу олорор, көҥүллээх уонна тус тыыттыллыбат буолар бырааптаах.","Хас биирдии киһи, ханна да сырыттар, бэйэтин правосубъектнай быһыытынан ааҕынар бырааптаах."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_sah.xml","speakers":"https://en.wikipedia.org/wiki/Yakut_language","glottolog":"https://glottolog.org/resource/languoid/id/yaku1245"}},{"name":"Mongolian","aka":["Монгол"],"family":"Mongolic-Khitan","branch":"Mongolic","script":"Cyrillic","lat":48.324,"lon":106.2887,"speakers":5000000,"region":"Asia","samples":["Хүн бүр төрж мэндлэхэд эрх чөлөөтэй, адилхан нэр төртэй, ижил эрхтэй байдаг. Оюун ухаан, нандин чанар заяасан хүн гэгч өөр хоорондоо ахан дүүгийн үзэл санаагаар харьцах учиртай.","Хүн бүр амьд явах, эрх чөлөөтэй байх, халдашгүй дархан байх эрхтэй.","Хэнийг ч дур мэдэн баривчлах, саатуулах буюу хөөн зайлуулах ёсгүй."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_khk.xml","speakers":"https://en.wikipedia.org/wiki/Mongolian_language","glottolog":"https://glottolog.org/resource/languoid/id/halh1238"}},{"name":"Uyghur","aka":["ئۇيغۇرچە"],"family":"Turkic","branch":"Turkestan (Karluk)","script":"Arabic","lat":43.88,"lon":87.38,"speakers":8000000,"region":"Asia","samples":["ھەممە ئادەم زانىدىنلا ئەركىن، ئىززەت-ھۆرمەت ۋە ھوقۇقتا باپباراۋەر بولۇپ تۇغۇلغان. ئۇلار ئەقىلغە ۋە ۋىجدانغا ئىگە ھەمدە بىر-بىرىگە قېرىنداشلىق مۇناسىۋىتىگە خاس روھ بىلەن موئامىلە قىلىشى كېرەك.","ھەممە ئادەم ھاياتلىقتىن، ئەركىنلىكتىن ۋە جىسمانىي بىخەتەرلىكتىن بەھرىمەن بولۇشقا ھوقۇقلۇق.","ھەممە ئادەم ھەرقانداق جايدا قانۇن ئالدىدىكى كىشىلىك ئىززىتىنى ئېتىراپ قىلدۇرۇشقا ھوقۇقلۇق."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_uig_arab.xml","speakers":"https://en.wikipedia.org/wiki/Uyghur_language","glottolog":"https://glottolog.org/resource/languoid/id/uigh1240"}},{"name":"Hindi","aka":["हिन्दी"],"family":"Indo-European","branch":"Indo-Aryan","script":"Devanagari","lat":25.0,"lon":77.0,"speakers":345000000,"region":"Asia","samples":["सभी मनुष्यों को गौरव और अधिकारों के मामले में जन्मजात स्वतन्त्रता और समानता प्राप्त है । उन्हें बुद्धि और अन्तरात्मा की देन प्राप्त है और परस्पर उन्हें भाईचारे के भाव से बर्ताव करना चाहिए ।","प्रत्येक व्यक्ति को जीवन, स्वाधीनता और वैयक्तिक सुरक्षा का अधिकार है ।","किसी को भी मनमाने ढंग से गिरफ़्तार, नज़रबन्द या देश-निष्कासित न किया जाएगा ।"],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_hin.xml","speakers":"https://en.wikipedia.org/wiki/Hindi","glottolog":"https://glottolog.org/resource/languoid/id/hind1269"}},{"name":"Urdu","aka":["اردو"],"family":"Indo-European","branch":"Indo-Aryan","script":"Arabic","lat":25.0,"lon":67.0,"speakers":78000000,"region":"Asia","samples":["تمام انسان آزاد اور حقوق و عزت کے اعتبار سے برابر پیدا ہوئے ہیں۔ انہیں ضمیر اور عقل ودیعت ہوئی ہے۔ اس لئے انہیں ایک دوسرے کے ساتھ بھائی چارے کا سلوک کرنا چاہیئے۔","ہر شخص کو اپنی جان، آزادی اور ذاتی تحفّظ کا حق ہے۔","ہر شخص کا حق ہے کہ ہر مقام پر قانون اس کی شخصیت کو تسلیم کرے۔"],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_urd.xml","speakers":"https://en.wikipedia.org/wiki/Urdu","glottolog":"https://glottolog.org/resource/languoid/id/urdu1245"}},{"name":"Bengali","aka":["Bangla","বাংলা"],"family":"Indo-European","branch":"Indo-Aryan","script":"Bengali","lat":24.0,"lon":90.0,"speakers":242000000,"region":"Asia","samples":["সমস্ত মানুষ স্বাধীনভাবে সমান মর্যাদা এবং অধিকার নিয়ে জন্মগ্রহণ করে। তাঁদের বিবেক এবং বুদ্ধি আছে; সুতরাং সকলেরই একে অপরের প্রতি ভ্রাতৃত্বসুলভ মনোভাব নিয়ে আচরণ করা উচিত।","জীবন, স্বাধীনতা এবং দৈহিক নিরাপত্তায় প্রত্যেকের অধিকার আছে।","আ‌ইনের সামনে প্রত্যেকের‌ই ব্যক্তি হিসেবে স্বীকৃতি লাভের অধিকার আছে।"],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_ben.xml","speakers":"https://en.wikipedia.org/wiki/Bengali_language","glottolog":"https://glottolog.org/resource/languoid/id/beng1280"}},{"name":"Punjabi","aka":["Panjabi","ਪੰਜਾਬੀ"],"family":"Indo-European","branch":"Indo-Aryan","script":"Gurmukhi","lat":30.0368,"lon":75.6702,"speakers":156700000,"region":"Asia","samples":["ਸਾਰਾ ਮਨੁੱਖੀ ਪਰਿਵਾਰ ਆਪਣੀ ਮਹਿਮਾ, ਸ਼ਾਨ ਅਤੇ ਹੱਕਾਂ ਦੇ ਪੱਖੋਂ ਜਨਮ ਤੋਂ ਹੀ ਆਜ਼ਾਦ ਹੈ ਅਤੇ ਸੁਤੇ ਸਿੱਧ ਸਾਰੇ ਲੋਕ ਬਰਾਬਰ ਹਨ । ਉਨ੍ਹਾਂ ਸਭਨਾ ਨੂੰ ਤਰਕ ਅਤੇ ਜ਼ਮੀਰ ਦੀ ਸੌਗਾਤ ਮਿਲੀ ਹੋਈ ਹੈ ਅਤੇ ਉਨ੍ਹਾਂ ਨੂੰ ਭਰਾਤਰੀਭਾਵ ਦੀ ਭਾਵਨਾ ਰਖਦਿਆਂ ਆਪਸ ਵਿਚ ਵਿਚਰਣਾ ਚਾਹੀਦਾ ਹੈ ।","ਹਰੇਕ ਮਨੁੱਖ ਨੂੰ ਜਿ਼ੰਦਗੀ ਜੀਊਣ, ਆਜ਼ਾਦੀ ਅਤੇ ਸੁਰੱਖਿਆ ਦਾ ਹੱਕ ਹੈ ।","ਹਰੇਕ ਵਿਅਕਤੀ ਨੂੰ ਕਾਨੂੰਨ ਸਾਹਮਣੇ ਇਕ ਇਨਸਾਨ ਵਜੋਂ ਮਿਲਣ ਦਾ ਹੱਕ ਮਿਲੇਗਾ ।"],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_pan.xml","speakers":"https://en.wikipedia.org/wiki/Punjabi_language","glottolog":"https://glottolog.org/resource/languoid/id/panj1256"}},{"name":"Marathi","aka":["मराठी"],"family":"Indo-European","branch":"Indo-Aryan","script":"Devanagari","lat":17.9344,"lon":76.6665,"speakers":83000000,"region":"Asia","samples":["सर्व मानवी व्यक्ति जन्मतःच स्वतंत्र आहेत व त्यांना समान प्रतिष्ठा व समान अधिकार आहेत. त्यांना विचारशक्ति व सदसविद्वेकबुद्धि लाभलेली आहे. व त्यांनी एकमेकांशी बंधुत्याच्या भावनेने आचरण करावे.","प्रत्येकास जगण्याचा, स्वातंत्र्य उपभोगण्याचा व सुरक्षित असण्याचा अधिकार आहे.","कोणालाहि स्वच्छंदतः अटक, स्थानबद्ध किंवा हद्दपार करता कामा नये."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_mar.xml","speakers":"https://en.wikipedia.org/wiki/Marathi_language","glottolog":"https://glottolog.org/resource/languoid/id/mara1378"}},{"name":"Gujarati","aka":["ગુજરાતી"],"family":"Indo-European","branch":"Indo-Aryan","script":"Gujarati","lat":22.687,"lon":71.0962,"speakers":57000000,"region":"Asia","samples":["પ્રતિષ્ઠા અને અધિકારોની દૃષ્ટિએ સર્વ માનવો જન્મથી સ્વતંત્ર અને સમાન હોય છે. તેમનામાં વિચારશક્તિ અને અંતઃકરણ હોય છે અને તેમણે પરસ્પર બંધુત્વની ભાવનાથી વર્તવું જોઇએ.","દરેક વ્યક્તિને જીવવાનો, સ્વતંત્રતાનો અને સ્વરક્ષણનો અધિકાર છે.","દરેક વ્યક્તિને દરેક હેકાણે કાયદાની સમક્ષ માનવ તરીકે સ્વીકાર કરાવવાનો અધિકાર છે."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_guj.xml","speakers":"https://en.wikipedia.org/wiki/Gujarati_language","glottolog":"https://glottolog.org/resource/languoid/id/guja1252"}},{"name":"Tamil","aka":["தமிழ்"],"family":"Dravidian","branch":"South Dravidian","script":"Tamil","lat":10.5202,"lon":78.826,"speakers":79000000,"region":"Asia","samples":["மனிதப் பிறிவியினர் சகலரும் சுதந்திரமாகவே பிறக்கின்றனர்; அவர்கள் மதிப்பிலும், உரிமைகளிலும் சமமானவர்கள், அவர்கள் நியாயத்தையும் மனச்சாட்சியையும் இயற்பண்பாகப் பெற்றவர்கள். அவர்கள் ஒருவருடனொருவர் சகோதர உணர்வுப் பாங்கில் நடந்துகொள்ளல் வேண்டும்.","வாழ்வதற்கும், சுதந்திரத்திற்கும் பாதுகாப்பிற்கும் சகலரும் உரிமையுடையோராவர்.","ஒவ்வொருவரும் எவ்விடத்திலும் சட்டத்தின் முன்னர் ஓர் ஆளாக ஏற்றுக்கொள்ளப்படுவதற்கு உரிமையுடையவராவர்."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_tam.xml","speakers":"https://en.wikipedia.org/wiki/Tamil_language","glottolog":"https://glottolog.org/resource/languoid/id/tami1289"}},{"name":"Telugu","aka":["తెలుగు"],"family":"Dravidian","branch":"South Dravidian","script":"Telugu","lat":16.4529,"lon":78.7024,"speakers":83000000,"region":"Asia","samples":["ప్రతిపత్తిస్వత్వముల విషయమున మానవులెల్లరును జన్మతః స్వతంత్రులును సమానులును నగుదురు. వారు వివేచన-అంతఃకరణ సంపన్నులగుటచే పరస్పరము భ్రాతృభావముతో వర్తింపవలయును.","జీవితరక్షణకు, స్వేచ్ఛకు, దేహరక్షకు, ప్రతి యొకరికిని హక్కు గలదు.","సర్వత్ర, విధిసమక్షమున నొక వ్యక్తిగా అంగీకరింపబడు నధికారము ప్రతి యొకరికిని గలదు."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_tel.xml","speakers":"https://en.wikipedia.org/wiki/Telugu_language","glottolog":"https://glottolog.org/resource/languoid/id/telu1262"}},{"name":"Kannada","aka":["ಕನ್ನಡ"],"family":"Dravidian","branch":"South Dravidian","script":"Kannada","lat":13.5878,"lon":76.1198,"speakers":44000000,"region":"Asia","samples":["ಎಲ್ಲಾ ಮಾನವರೂ ಸ್ವತಂತ್ರರಾಗಿಯೇ ಜನಿಸಿದ್ದಾರೆ. ಹಾಗೂ ಘನತೆ ಮತ್ತು ಹಕ್ಕುಗಳಲ್ಲಿ ಸಮಾನರಾಗಿದ್ದಾರೆ. ವಿವೇಕ ಮತ್ತು ಅಂತಃಕರಣಗಳನ್ನು ಪಡೆದವರಾದ್ದರಿಂದ ಅವರು ಪರಸ್ಪರ ಸಹೋದರ ಭಾವದಿಂದ ವರ್ತಿಸಬೇಕು.","ಪ್ರತಿಯೊಬ್ಬನಿಗೂ ಜೀವನದ ಸ್ವಾತಂತ್ರ್ಯದ ಮತ್ತು ಆತ್ಮಸಂರಕ್ಷೆಯ ಹಕ್ಕುಂಟು.","ಮನಬಂದಂತೆ ಯಾವನನ್ನು ಬಂಧಿಸಲೂ, ಸೆರೆ ಅಥವಾ ಗಡಿಪಾರಿಗೆ ಒಳಪಡಿಸುವಹಾಗಿಲ್ಲ."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_kan.xml","speakers":"https://en.wikipedia.org/wiki/Kannada","glottolog":"https://glottolog.org/resource/languoid/id/nucl1305"}},{"name":"Malayalam","aka":["മലയാളം"],"family":"Dravidian","branch":"South Dravidian","script":"Malayalam","lat":9.5921,"lon":76.7651,"speakers":37000000,"region":"Asia","samples":["മനുഷ്യരെല്ലാവരും തുല്യാവകാശങ്ങളോടും അന്തസ്സോടും സ്വാതന്ത്ര്യത്തോടുംകൂടി ജനിച്ചിട്ടുള്ളവരാണ്‌. അന്യോന്യം ഭ്രാതൃഭാവത്തോടെ പെരുമാറുവാനാണ്‌ മനുഷ്യന്നു വിവേകബുദ്ധിയും മനസ്സാക്ഷിയും സിദ്ധമായിരിക്കുന്നത്‌.","സ്വയരക്ഷാബോധത്തോടും സ്വാതന്ത്ര്യത്തോടും കൂടി ജീവിക്കുവാന്‍ ഏതൊരാള്‍ക്കും അധികാരമുണ്ട്‌.","നിയമദൃഷ്ട്യാ ഏതൊരാള്‍ക്കും ഏതൊരു സ്ഥലത്തും അംഗീകരണത്തിനു അവകാശമുണ്ട്‌."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_mal.xml","speakers":"https://en.wikipedia.org/wiki/Malayalam","glottolog":"https://glottolog.org/resource/languoid/id/mala1464"}},{"name":"Sinhala","aka":["Sinhalese","සිංහල"],"family":"Indo-European","branch":"Indo-Aryan","script":"Sinhala","lat":8.0,"lon":81.0,"speakers":18000000,"region":"Asia","samples":["සියලු මනුෂ්‍යයෝ නිදහස්ව උපත ලබා ඇත. ගරුත්වයෙන් හා අයිතිවාසිකම්වලින් සමාන වෙති. යුක්ති අයුක්ති පිළිබඳ හැඟීමෙන් හා හෘදය සාක්ෂියෙන් යුත් ඔවුන්, ඔවුනොවුන්ට සැළකිය යුත්තේ සහෝදරත්වය පිළිබඳ හැඟීමෙනි.","සෑම පුද්ගලයෙකුටම ජීවත්වීමටත් නිදහස්ව සිතීමටත් පෞද්ගලික ආරක්ෂාවටත් හිමිකම් ඇත්තේය.","සෑම අවස්ථාවකදී ම නීතිය ඉදිරියේ පුද්ගලයකු වශයෙන් පිළිගනු ලැබීමේ අයිතිය සෑම කෙනෙකුම සතුය."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_sin.xml","speakers":"https://en.wikipedia.org/wiki/Sinhala_language","glottolog":"https://glottolog.org/resource/languoid/id/sinh1246"}},{"name":"Nepali","aka":["नेपाली"],"family":"Indo-European","branch":"Indo-Aryan","script":"Devanagari","lat":28.0,"lon":85.0,"speakers":19000000,"region":"Asia","samples":["सबै व्यक्ति हरू जन्मजात स्वतन्त्र हुन ती सबैको समान अधिकार र महत्व छ। निजहरूमा विचार शक्ति र सद्धिचार भएकोले निजहरूले आपसमा भातृत्वको भावना बाट व्यवहार गर्नु पर्छ।","प्रत्येक व्यक्तिलाई व्यक्तिक स्वतन्त्रता र आत्मरक्षाको अधिकार हुनेछ।","कसैलाई पनि मनमानी ढाँगले देश निष्कासित वा गिरफ्तार वा नजर बन्द गरिने छैन।"],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_nep.xml","speakers":"https://en.wikipedia.org/wiki/Nepali_language","glottolog":"https://glottolog.org/resource/languoid/id/nepa1254"}},{"name":"Bhojpuri","aka":["भोजपुरी"],"family":"Indo-European","branch":"Indo-Aryan","script":"Devanagari","lat":26.4585,"lon":84.8171,"speakers":52200000,"region":"Asia","samples":["सबहि लोकानि आजादे जम्मेला आओर ओखिनियो के बराबर सम्मान आओर अधिकार प्राप्त हवे। ओखिनियो के पास समझ-बूझ आओर अंत:करण के आवाज होखता आओर हुनको के दोसरा के साथ भाईचारा के बेवहार करे के होखला।","सबहि के जीवन जीए के आजादी आओर अपन सुरक्षा के अधिकार हवे।","केहु के बिना कोनो कारण के कैद, अज्ञातवास या देशनिकाला नइखे देल जा सकेला।"],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_bho.xml","speakers":"https://en.wikipedia.org/wiki/Bhojpuri_language","glottolog":"https://glottolog.org/resource/languoid/id/bhoj1244"}},{"name":"Dhivehi","aka":["Maldivian","ދިވެހި"],"family":"Indo-European","branch":"Indo-Aryan","script":"Thaana","lat":1.9285,"lon":73.5443,"speakers":504829,"region":"Asia","samples":["ހުރިހާ އިންސާނުންވެސް ދުނިޔެއަށް އުފަންވަނީ، މިނިވަންކަމުގައި، ހަމަހަމަ ޙައްޤުތަކަކާއެކު، ހަމަހަމަ ދަރަޖައެއްގައި ކަމޭހިތެވިގެންވާ ބައެއްގެ ގޮތުގައެވެ. ހެޔޮ ވިސްނުމާއި، ހެޔޮބުއްދީގެ ބާރު އެމީހުންނަށް ލިބިގެންވެއެވެ. އަދި އެކަކު އަނެކަކާމެދު އެމީހުން މުޢާމަލާތް ކުރަންވާނީ، އުޚުއްވަތްތެރިކަމުގެ ރޫޙެއްގައެވެ.","ހަމަ ކޮންމެ މީހަކަށްމެ ދިރިހުރުމުގެ ޙައްޤާއި، މިނިވަންކަމުގެ ޙައްޤާއި، ތިމާގެހަށިގަނޑާއި ނަފްސުގެ ރައްކާތެރިކަމުގެ ޙައްޤު ލިބިގެންވެއެވެ.","ހަމަ ކޮންމެ މީހަކަށްމެ، ޤާނޫނުގެ ކުރިމަތީގައި، އެއީ ފަރުދެއް ކަމުގައި ބަލައިގަނެ ޤަބޫލުކުރުމުގެ ޙައްޤު، ކޮންމެ ތަނެއްގައި އޭނާ ހުރި ކަމުގައިވީ ނަމަވެސް، ލިބިގެންވެއެވެ."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_div.xml","speakers":"https://en.wikipedia.org/wiki/Maldivian_language","glottolog":"https://glottolog.org/resource/languoid/id/dhiv1236"}},{"name":"Tibetan","aka":["བོད་སྐད་"],"family":"Sino-Tibetan","branch":"Bodish","script":"Tibetan","lat":28.3681,"lon":90.1872,"speakers":1200000,"region":"Asia","samples":["འགྲོ་བ་མིའི་རིགས་རྒྱུད་ཡོངས་ལ་སྐྱེས་ཙམ་ཉིད་ནས་ཆེ་མཐོངས་དང༌། ཐོབ་ཐངགི་རང་དབང་འདྲ་མཉམ་དུ་ཡོད་ལ། ཁོང་ཚོར་རང་བྱུང་གི་བློ་རྩལ་དང་བསམ་ཚུལ་བཟང་པོ་འདོན་པའི་འོས་བབས་ཀྱང་ཡོད། དེ་བཞིན་ཕན་ཚུན་གཅིག་གིས་གཅིག་ལ་བུ་སྤུན་གྱི་འདུ་ཤེས་འཛིན་པའི་བྱ་སྤྱོད་ཀྱང་ལག་ལེན་བསྟར་དགོས་པ་ཡིན༎","སྐྱེ་བོ་རེ་རེར་སྲོག་འཚོ་བ་དང༌། རང་དབང་ལ་སྤྱོད་པ། ལུས་པོ་བདེ་སྐུང་བཅས་ཀྱི་ཐོབ་ཐང་ཡོད༎","སྐྱེ་བོ་རེ་རེར་ཁྲིམས་ཀྱི་མདུན་ས་གང་འདྲ་ཞིག་ཏུའང་འགྲོ་བ་མི་ཞིག་ལ་ངོས་འཛིན་ཆ་འཇོག་དགོས་པའི་ཐོབ་ཐང་ཡོད༎"],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_bod.xml","speakers":"https://en.wikipedia.org/wiki/Lhasa_Tibetan","glottolog":"https://glottolog.org/resource/languoid/id/tibe1272"}},{"name":"Mizo","aka":["Lushai"],"family":"Sino-Tibetan","branch":"Kuki-Chin","script":"Latin","lat":22.6138,"lon":92.6247,"speakers":1000000,"region":"Asia","samples":["Mi zawng zawng hi zalêna piang kan ni a, zahawmna leh dikna chanvoah intluk tlâng vek kan ni. Chhia leh tha hriatna fîm neia siam kan nih avangin kan mihring puite chungah inunauna thinlung kan pu tlat tur a ni.","Mitinte hian nung turin dikna kan nei vek a, zalênna leh mimal nun thlamuanna te hi kan chanvo a ni.","Mi tumah apâwng ataka man emaw, hrên luih emaw leh hnawhchhuah emaw tur a ni lo."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_lus.xml","speakers":"https://en.wikipedia.org/wiki/Mizo_language","glottolog":"https://glottolog.org/resource/languoid/id/lush1249"}},{"name":"Mandarin Chinese","aka":["Chinese","Mandarin","普通话"],"family":"Sino-Tibetan","branch":"Sinitic","script":"Chinese characters","lat":40.0209,"lon":116.228,"speakers":990000000,"region":"Asia","samples":["人人生而自由，在尊严和权利上一律平等。他们赋有理性和良心，并应以兄弟关系的精神相对待。","人人有权享有生命、自由和人身安全。","任何人不得加以任意逮捕、拘禁或放逐。"],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_cmn_hans.xml","speakers":"https://en.wikipedia.org/wiki/Mandarin_Chinese","glottolog":"https://glottolog.org/resource/languoid/id/mand1415"}},{"name":"Cantonese","aka":["Yue Chinese","粵語"],"family":"Sino-Tibetan","branch":"Sinitic","script":"Chinese characters","lat":23.0,"lon":113.0,"speakers":85000000,"region":"Asia","samples":["人人生而平等，喺尊严同埋权利上一律平等。佢哋有理性同埋良心，而且应当以兄弟关系嘅精神相对待。","人人有权享有生命、自由同埋人身安全。","任何人唔好加以任意逮捕、拘禁或放逐。"],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_yue.xml","speakers":"https://en.wikipedia.org/wiki/Yue_Chinese","glottolog":"https://glottolog.org/resource/languoid/id/yuec1235"}},{"name":"Wu Chinese","aka":["Shanghainese","吴语"],"family":"Sino-Tibetan","branch":"Sinitic","script":"Chinese characters","lat":29.8621,"lon":119.682,"speakers":83000000,"region":"Asia","samples":["人人生而自由，拉尊严脱仔权利上一律平等。伊拉有理性脱仔良心，并应以兄弟关系个精神相对待。","人人有权享有生命、自由脱仔人身安全。","任何人勿要加以任意逮捕、拘禁或放逐。"],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_wuu.xml","speakers":"https://en.wikipedia.org/wiki/Wu_Chinese","glottolog":"https://glottolog.org/resource/languoid/id/wuch1236"}},{"name":"Min Nan","aka":["Hokkien","Southern Min","Taiwanese","闽南语"],"family":"Sino-Tibetan","branch":"Sinitic","script":"Chinese characters","lat":24.5,"lon":118.17,"speakers":34000000,"region":"Asia","samples":["人人生而自由，在尊严合权利上一律平等。因赋有脾胃合道行，并着以兄弟关系的精神相对待。","人人过过有权享有生命、自由合人身安全。.","任何人勿会用加以任意枇、拘禁抑放逐。"],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_nan.xml","speakers":"https://en.wikipedia.org/wiki/Southern_Min","glottolog":"https://glottolog.org/resource/languoid/id/minn1241"}},{"name":"Japanese","aka":["日本語","Nihongo"],"family":"Japonic","branch":"Japanesic","script":"Japanese (Kanji and Kana)","lat":35.0,"lon":135.0,"speakers":123000000,"region":"Asia","samples":["すべての人間は、生まれながらにして自由であり、かつ、尊厳と権利とについて平等である。人間は、理性と良心とを授けられており、互いに同胞の精神をもって行動しなければならない。","すべての人は、生命、自由及び身体の安全に対する権利を有する。","何人も、ほしいままに逮捕、拘禁、又は追放されることはない。"],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_jpn.xml","speakers":"https://en.wikipedia.org/wiki/Japanese_language","glottolog":"https://glottolog.org/resource/languoid/id/nucl1643"}},{"name":"Korean","aka":["한국어"],"family":"Koreanic","branch":null,"script":"Hangul","lat":37.54,"lon":126.98,"speakers":81000000,"region":"Asia","samples":["모든 인간은 태어날 때부터 자유로우며 그 존엄과 권리에 있어 동등하다. 인간은 천부적으로 이성과 양심을 부여받았으며 서로 형제애의 정신으로 행동하여야 한다.","모든 사람은 생명과 신체의 자유와 안전에 대한 권리를 가진다.","어느 누구도 자의적으로 체포, 구금 또는 추방되지 아니한다."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_kor.xml","speakers":"https://en.wikipedia.org/wiki/Korean_language","glottolog":"https://glottolog.org/resource/languoid/id/kore1280"}},{"name":"Vietnamese","aka":["Tiếng Việt"],"family":"Austroasiatic","branch":"Vietic","script":"Latin","lat":20.6812,"lon":105.7741,"speakers":86000000,"region":"Asia","samples":["Tất cả mọi người sinh ra đều được tự do và bình đẳng về nhân phẩm và quyền. Mọi con người đều được tạo hoá ban cho lý trí và lương tâm và cần phải đối xử với nhau trong tình bằng hữu.","Mọi người đều có quyền sống, tự do và an toàn cá nhân.","Không ai bị bắt, giam giữ hay đày đi nơi khác một cách độc đoán."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_vie.xml","speakers":"https://en.wikipedia.org/wiki/Vietnamese_language","glottolog":"https://glottolog.org/resource/languoid/id/viet1252"}},{"name":"Thai","aka":["ภาษาไทย"],"family":"Tai-Kadai","branch":"Tai","script":"Thai","lat":14.192,"lon":100.671,"speakers":27000000,"region":"Asia","samples":["มนุษย์ทั้งหลายเกิดมามีอิสระและเสมอภาคกันในเกียรติศักดิ์และสิทธิ ต่างมีเหตุผลและมโนธรรม และควรปฏิบัติต่อกันด้วยเจตนารมณ์แห่งภราดรภาพ","คนทุกคนมีสิทธิในการดำรงชีวิต เสรีภาพ และความมั่นคงแห่งตัวตน","บุคคลใดจะถูกจับกุม กักขัง หรือเนรเทศไปต่างถิ่นโดยพลการไม่ได้"],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_tha.xml","speakers":"https://en.wikipedia.org/wiki/Thai_language","glottolog":"https://glottolog.org/resource/languoid/id/thai1261"}},{"name":"Lao","aka":["Laotian","ພາສາລາວ"],"family":"Tai-Kadai","branch":"Tai","script":"Lao","lat":19.0,"lon":102.46,"speakers":3700000,"region":"Asia","samples":["ມະນຸດເກີດມາມີສິດເສລີພາບ ແລະ ສະເໝີໜ້າກັນໃນທາງກຽດຕິສັກ ແລະ ທາງສິດດ້ວຍມະນຸດມີສະຕິສຳປັດຊັນຍະ(ຮູ້ດີຮູ້ຊົ່ວ)ແລະມີມະໂນທຳຈື່ງຕ້ອງປະພຶດຕົນຕໍ່ກັນໃນທາງພີ່ນ້ອງ.","ບຸກຄົນທຸກຄົນມີສິດດຳລົງຊີວິດ ມີສິດເສລີພາບ ແລະ ຄວາມປອດໄພໃນຕົວ.","ບຸກຄົນໃດບໍ່ອາດຖືກຈັບກຸມຄຸມຂັງ ແລະ ເນລະເທດໂດຍລຳພັງໃຈເລີຍ."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_lao.xml","speakers":"https://en.wikipedia.org/wiki/Lao_language","glottolog":"https://glottolog.org/resource/languoid/id/laoo1244"}},{"name":"Khmer","aka":["Cambodian","ភាសាខ្មែរ"],"family":"Austroasiatic","branch":"Khmeric","script":"Khmer","lat":12.0515,"lon":105.015,"speakers":19000000,"region":"Asia","samples":["មនុស្សទាំងអស់ កើតមកមានសេរីភាព និងសមភាព ក្នុងផ្នែកសេចក្ដីថ្លៃថ្នូរនិងសិទ្ធិ។ មនុស្ស មានវិចារណញ្ញាណនិងសតិសម្បជញ្ញៈជាប់ពីកំណើត ហើយគប្បីប្រព្រឹត្ដចំពោះគ្នាទៅវិញទៅមកក្នុងស្មារតីភាតរភាពជាបងប្អូន។","បុគ្គលម្នាក់ៗ មានសិទ្ធិរស់រានមានជីវិត សេរីភាព និងសន្ដិសុខផ្ទាល់ខ្លួន។","គ្មានជនណាម្នាក់ ត្រូវបានចាប់ខ្លួន ឃុំខ្លួន ឬនិរទេសខ្លួន តាមអំពើចិត្ដឡើយ។"],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_khm.xml","speakers":"https://en.wikipedia.org/wiki/Khmer_language","glottolog":"https://glottolog.org/resource/languoid/id/cent1989"}},{"name":"Burmese","aka":["Myanmar","မြန်မာဘာသာ"],"family":"Sino-Tibetan","branch":"Lolo-Burmese","script":"Burmese","lat":20.7926,"lon":93.9665,"speakers":33000000,"region":"Asia","samples":["လူတိုင်းသည် တူညီ လွတ်လပ်သော ဂုဏ်သိက္ခာဖြင့် လည်းကောင်း၊ တူညီလွတ်လပ်သော အခွင့်အရေးများဖြင့် လည်းကောင်း၊ မွေးဖွားလာသူများ ဖြစ်သည်။ ထိုသူတို့၌ ပိုင်းခြား ဝေဖန်တတ်သော ဉာဏ်နှင့် ကျင့်ဝတ် သိတတ်သော စိတ်တို့ရှိကြ၍ ထိုသူတို့သည် အချင်းချင်း မေတ္တာထား၍ ဆက်ဆံကျင့်သုံးသင့်၏။","လူတိုင်း၌ အသက်ရှင်ရန် လွတ်လပ်ခွင့်နှင့် လုံခြုံစိတ်ချခွင့် ရှိသည်။","လူတိုင်းတွင် ဥပဒေအရာ၌ လူပုဂ္ဂိုလ်တစ်ဦး အဖြစ်ဖြင့် အရာခပ်သိမ်းတွင် အသိအမှတ် ပြုခြင်းကို ခံယူပိုင်ခွင့်ရှိသည်။"],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_mya.xml","speakers":"https://en.wikipedia.org/wiki/Burmese_language","glottolog":"https://glottolog.org/resource/languoid/id/nucl1310"}},{"name":"Indonesian","aka":["Bahasa Indonesia"],"family":"Austronesian","branch":"Malayo-Chamic","script":"Latin","lat":-7.3346,"lon":109.716,"speakers":75000000,"region":"Asia","samples":["Semua orang dilahirkan merdeka dan mempunyai martabat dan hak-hak yang sama. Mereka dikaruniai akal dan hati nurani dan hendaknya bergaul satu sama lain dalam semangat persaudaraan.","Setiap orang berhak atas penghidupan, kebebasan dan keselamatan individu.","Tak seorang pun boleh ditangkap, ditahan atau dibuang dengan sewenang-wenang."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_ind.xml","speakers":"https://en.wikipedia.org/wiki/Indonesian_language","glottolog":"https://glottolog.org/resource/languoid/id/indo1316"}},{"name":"Malay","aka":["Bahasa Melayu"],"family":"Austronesian","branch":"Malayo-Chamic","script":"Latin","lat":1.8586,"lon":103.0,"speakers":90000000,"region":"Asia","samples":["Semua manusia dilahirkan bebas dan samarata dari segi kemuliaan dan hak-hak. Mereka mempunyai pemikiran dan perasaan hati dan hendaklah bertindak di antara satu sama lain dengan semangat persaudaraan.","Setiap orang adalah berhak kepada nyawa, kebebasan dan keselamatan diri.","Tiada sesiapa pun boleh dikenakan tangkapan, tahanan atau pembuangan negeri secara sewenang-wenangnya."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_mly_latn.xml","speakers":"https://en.wikipedia.org/wiki/Malay_language","glottolog":"https://glottolog.org/resource/languoid/id/mala1479"}},{"name":"Javanese","aka":["Basa Jawa"],"family":"Austronesian","branch":"Javanesic","script":"Latin","lat":-7.001,"lon":109.287,"speakers":68000000,"region":"Asia","samples":["Saben uwong kalairake kanthi mardika lan darbe martabat lan hak-hak kang padha. Kabeh pinaringan akal lan kalbu sarta kaajab pasrawungan anggone memitran siji lan sijine kanthi jiwo sumadulur.","Saben uwong nduweni hak ingatasing uripe, bebasing uripe lan kaslametane minongko pribadi (individu).","Ora ana siji wae uwong kang kena ditangkep, ditahan utawa kasingkirake kanthi sawenang-wenang."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_jav.xml","speakers":"https://en.wikipedia.org/wiki/Javanese_language","glottolog":"https://glottolog.org/resource/languoid/id/java1254"}},{"name":"Sundanese","aka":["Basa Sunda"],"family":"Austronesian","branch":"Malayo-Polynesian","script":"Latin","lat":-6.8971,"lon":107.106,"speakers":32000000,"region":"Asia","samples":["Sakumna jalma gubrag ka alam dunya teh sifatna merdika jeung boga martabat katut hak-hak anu sarua . Maranehna dibere akal jeung hate nurani, campur-gaul jeung sasamana aya dina sumanget duduluran.","Sakumna jalma, saha bae, boga hak kana kahirupanana, kabebasanana sarta kasalamatenana.","Sing saha bae nampa pangaku nu sarua di hareupeun hukum, di mana bae ayana."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_sun.xml","speakers":"https://en.wikipedia.org/wiki/Sundanese_language","glottolog":"https://glottolog.org/resource/languoid/id/sund1252"}},{"name":"Tagalog","aka":["Filipino","Wikang Tagalog"],"family":"Austronesian","branch":"Philippine","script":"Latin","lat":14.06,"lon":121.747,"speakers":33000000,"region":"Asia","samples":["Ang lahat ng tao'y isinilang na malaya at pantay-pantay sa karangalan at mga karapatan. Sila'y pinagkalooban ng katwiran at budhi at dapat magpalagayan ang isa't isa sa diwa ng pagkakapatiran.","Ang bawat tao'y may karapatan sa buhay, kalayaan at kapanatagan ng sarili.","Walang sino mang ipaiilalim sa di-makatwirang pagdakip, pagpigil o pagpapatapon."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_tgl.xml","speakers":"https://en.wikipedia.org/wiki/Tagalog_language","glottolog":"https://glottolog.org/resource/languoid/id/taga1270"}},{"name":"Cebuano","aka":["Bisaya","Sinugboanon"],"family":"Austronesian","branch":"Philippine","script":"Latin","lat":8.388,"lon":124.367,"speakers":20000000,"region":"Asia","samples":["Ang tanang katawhan gipakatawo nga may kagawasan ug managsama sa kabililhon. Sila gigasahan sa salabutan ug tanlag og mag-ilhanay isip managsoon sa usa'g-usa diha sa diwa sa ospiritu.","Ang matag usa adunay katungod sa kinabuhi, kaugalingnan ug seguridad sa pagkatawo.","Ang matag usa adunay katungod nga ilhon isip tawo atubangan sa balaod."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_ceb.xml","speakers":"https://en.wikipedia.org/wiki/Cebuano_language","glottolog":"https://glottolog.org/resource/languoid/id/cebu1242"}},{"name":"Ilocano","aka":["Iloko"],"family":"Austronesian","branch":"Philippine","script":"Latin","lat":15.9361,"lon":120.993,"speakers":8700000,"region":"Asia","samples":["Amin nga tao nga sibibiag ket naiyanak a siwawayawaya ken addaan iti agpapada nga dayaw ken kalintegan. Naikkanda ti panagikalintegan ken konsensya a nasken ti panagtitinnulong iti meysa ken meysa iti espiritu nga nainkak-absatan.","Iti tunggal meysa adda kalinteganna ti biag, nga agwayawaya ken kinatalged nga kas tao.","Tunggal meysa addaan kalintegan a bigbigen sadinoman iti ayanna nga kas meysa nga tao iti sangnguanan ti linteg."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_ilo.xml","speakers":"https://en.wikipedia.org/wiki/Ilocano_language","glottolog":"https://glottolog.org/resource/languoid/id/ilok1237"}},{"name":"Balinese","aka":["Basa Bali"],"family":"Austronesian","branch":"Malayo-Polynesian","script":"Latin","lat":-8.3571,"lon":115.075,"speakers":3300000,"region":"Asia","samples":["Sami manusane sane nyruwadi wantah merdeka tur maduwe kautamaan lan hak-hak sane pateh. Sami kalugrain papineh lan idep tur mangdane pada masawitra melarapan semangat pakulawargaan.","Saluiring manusa wenang ring hak hidup, kebebasan lan kerahayuan suwang-suwang.","Sapasira ugi nenten dados ketangkep, ketahan wiadin kakutang sakita arep."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_ban.xml","speakers":"https://en.wikipedia.org/wiki/Balinese_language","glottolog":"https://glottolog.org/resource/languoid/id/bali1278"}},{"name":"Minangkabau","aka":["Baso Minang"],"family":"Austronesian","branch":"Malayo-Chamic","script":"Latin","lat":-0.896,"lon":100.44,"speakers":5500000,"region":"Asia","samples":["Sadonyo manusia dilahiakan mardeka dan punyo martabat sarato hak-hak nan samo. Mareka dikaruniai aka jo hati nurani, supayo satu samo lain bagaul sarupo urang badunsanak.","Tiok urang punyo hak untuak iduik, untuak mardeka, dan kasalamatan salaku manusia pribadi.","Indak surang pun buliah ditangkok, ditahan atau diasiangkan sacaro sawenang-wenang."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_min.xml","speakers":"https://en.wikipedia.org/wiki/Minangkabau_language","glottolog":"https://glottolog.org/resource/languoid/id/mina1268"}},{"name":"Tetum","aka":["Tetun"],"family":"Austronesian","branch":"Malayo-Polynesian","script":"Latin","lat":-9.1122,"lon":125.528,"speakers":null,"region":"Asia","samples":["Ema hotu hotu moris hanesan ho dignidade ho direitu. Sira hotu iha hanoin, konsiensia n'e duni tenki hare malu hanesan espiritu maun-alin.","Ema hotu hotu iha direitu atu moris, liberdade ho seguransa ba ema nia an.","Labele kaer ema ida naran deit, kadeia ka ezilio."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_tet.xml","speakers":"https://en.wikipedia.org/wiki/Tetum_language","glottolog":"https://glottolog.org/resource/languoid/id/tetu1245"}},{"name":"Hmong","aka":["Hmong Njua","Mong Leng"],"family":"Hmong-Mien","branch":"Hmongic","script":"Latin","lat":22.5638,"lon":101.95,"speakers":4500000,"region":"Asia","samples":["Cuat lenx cuat dol bongb deul ndax dex douf muax zif youx, nyaob shout zunb yinx tab ndas dos id, dax zis ib suk. Nil buab daf lol jaox muax lid xinf hlub hout tab liangx xinb shab nzhuk, yinf gaib keuk suk gud dix mol lol nit jinb shenx lol shib daf shib hlad.","Cuat lenx cuat dol muax ndos xangd sheuf jax shad, zif youx tab renx shenb angb qinx.","Cuat lenx cuat dol nyaob lob deb qeut dus dis muax ndos lenl zos yos nyaob ndeuf ged jait nit renx gex."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_blu.xml","speakers":"https://en.wikipedia.org/wiki/Hmong_language","glottolog":"https://glottolog.org/resource/languoid/id/hmon1264"}},{"name":"Swahili","aka":["Kiswahili"],"family":"Atlantic-Congo","branch":"Bantu","script":"Latin","lat":-8.2561,"lon":37.624,"speakers":4000000,"region":"Africa","samples":["Watu wote wamezaliwa huru, hadhi na haki zao ni sawa. Wote wamejaliwa akili na dhamiri, hivyo yapasa watendeane kindugu.","Kila mtu ana haki ya kuishi, haki ya uhuru, na haki ya kulindwa nafsi yake.","Mbele ya sheria kila mtu ana haki ya kutambulika kama mtu."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_swh.xml","speakers":"https://en.wikipedia.org/wiki/List_of_languages_by_total_number_of_speakers","glottolog":"https://glottolog.org/resource/languoid/id/swah1253"}},{"name":"Yoruba","aka":["Yorùbá"],"family":"Atlantic-Congo","branch":"Defoid","script":"Latin","lat":7.1535,"lon":3.6723,"speakers":48000000,"region":"Africa","samples":["Gbogbo ènìyàn ni a bí ní òmìnira; iyì àti ẹ̀tọ́ kọ̀ọ̀kan sì dọ́gba. Wọ́n ní ẹ̀bùn ti làákàyè àti ti ẹ̀rí‐ọkàn, ó sì yẹ kí wọn ó máa hùwà sí ara wọn gẹ́gẹ́ bí ọmọ ìyá.","Ẹnì kọ̀ọ̀kan ló ní ẹ̀tọ́ láti wà láàyè, ẹ̀tọ́ sí òmìnira àti ẹ̀tọ́ sí ààbò ara rẹ̀.","Ẹnì kọ̀ọ̀kan ló ní ẹ̀tọ́ pé kí a kà á sí gẹ́gẹ́ bí ènìyàn lábẹ́ òfin ní ibi gbogbo."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_yor.xml","speakers":"https://en.wikipedia.org/wiki/Yoruba_language","glottolog":"https://glottolog.org/resource/languoid/id/yoru1245"}},{"name":"Igbo","aka":["Asụsụ Igbo"],"family":"Atlantic-Congo","branch":"Igboid","script":"Latin","lat":4.627,"lon":7.2344,"speakers":34000000,"region":"Africa","samples":["A mụrụ mmadụ nile n'ohere nakwa nha anya ugwu na ikike. E nyere ha uche na mmụọ ime ihe ziri ezi nke na ha kwesiri ịkpaso ibe ha agwa n'obi nwanne na nwanne.","Onye ọ bụla nwere ikike inwe ndụ, ohere na nchedo nke onwe ya.","Onye ọ bụla nwere ikike nkwanyere ugwu dị ka mmadụ ebe ọ bụla n'usoro iwu."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_ibo.xml","speakers":"https://en.wikipedia.org/wiki/Igbo_language","glottolog":"https://glottolog.org/resource/languoid/id/nucl1417"}},{"name":"Hausa","aka":["Harshen Hausa"],"family":"Afro-Asiatic","branch":"Chadic","script":"Latin","lat":11.1513,"lon":8.7804,"speakers":58000000,"region":"Africa","samples":["Su dai ’yan-adam, ana haifuwarsu ne duka ’yantattu, kuma kowannensu na da mutunci da hakkoki daidai da na kowa. Suna da hankali da tunani, saboda haka duk abin da za su aikata wa juna, ya kamata su yi shi a cikin ’yan-uwanci.","Kowane mutum na da hakkin rayuwa, da zamantowa cikin ’yanci da samun a kiyaye halittarsa.","Kowane mutum na da hakkin a ko'ina a san da darajar halittarsa a huskar doka."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_hau_NG.xml","speakers":"https://en.wikipedia.org/wiki/Hausa_language","glottolog":"https://glottolog.org/resource/languoid/id/haus1257"}},{"name":"Zulu","aka":["isiZulu"],"family":"Atlantic-Congo","branch":"Bantu","script":"Latin","lat":-28.9,"lon":30.2,"speakers":12000000,"region":"Africa","samples":["Bonke abantu bazalwa bekhululekile belingana ngesithunzi nangamalungelo. Bahlanganiswe wumcabango nangunembeza futhi kufanele baphathane ngomoya wobunye.","Wonke umuntu unelungelo lempilo, lenkululeko nelokuphepha.","Akekho oyoboshwa, avelelwe noma adingiswe ngokungekho emthethweni."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_zul.xml","speakers":"https://en.wikipedia.org/wiki/Zulu_language","glottolog":"https://glottolog.org/resource/languoid/id/zulu1248"}},{"name":"Xhosa","aka":["isiXhosa"],"family":"Atlantic-Congo","branch":"Bantu","script":"Latin","lat":-31.0389,"lon":28.0769,"speakers":8000000,"region":"Africa","samples":["Bonke abantu bazalwa bekhululekile belingana ngesidima nangokweemfanelo. Bonke abantu banesiphiwo sesazela nesizathu sokwenza isenzo ongathanda ukuba senziwe kumzalwane wakho.","Wonke umntu unelungelo lokuphila, inkululeko kunye nokhuseleko.","Wonke umntu unelungelo lokwamkelwa yonke indawo njengomntu phambi komthetho."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_xho.xml","speakers":"https://en.wikipedia.org/wiki/Xhosa_language","glottolog":"https://glottolog.org/resource/languoid/id/xhos1239"}},{"name":"Afrikaans","aka":[],"family":"Indo-European","branch":"Germanic","script":"Latin","lat":-31.6327,"lon":20.4636,"speakers":7200000,"region":"Africa","samples":["Alle menslike wesens word vry, met gelyke waardigheid en regte, gebore. Hulle het rede en gewete en behoort in die gees van broederskap teenoor mekaar op te tree.","Elkeen het die reg tot lewe, vryheid en sekuriteit van persoon.","Elkeen het oral die reg tot erkenning as ’n persoon voor die reg."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_afr.xml","speakers":"https://en.wikipedia.org/wiki/Afrikaans","glottolog":"https://glottolog.org/resource/languoid/id/afri1274"}},{"name":"Amharic","aka":["አማርኛ"],"family":"Afro-Asiatic","branch":"Semitic","script":"Ge'ez","lat":11.7082,"lon":39.5435,"speakers":35000000,"region":"Africa","samples":["የሰው፡ልጅ፡ሁሉ፡ሲወለድ፡ነጻና፡በክብርና፡በመብትም፡እኩልነት፡ያለው፡ነው።፡የተፈጥሮ፡ማስተዋልና፡ሕሊና፡ስላለው፡አንዱ፡ሌላውን፡በወንድማማችነት፡መንፈስ፡መመልከት፡ይገባዋል።","እያንዳንዱ፡ሰው፡የመኖር፣፡በነጻነትና፡በሰላም፡የመኖሩ፡መጠበቅ፡መብት፡አለው።","እያንዳንዱ፡ሰው፡በሕግ፡ፊት፡በሰው፡ዘርነቱ፡የመታወቅ፡መብት፡አለው።"],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_amh.xml","speakers":"https://en.wikipedia.org/wiki/Amharic","glottolog":"https://glottolog.org/resource/languoid/id/amha1245"}},{"name":"Tigrinya","aka":["ትግርኛ"],"family":"Afro-Asiatic","branch":"Semitic","script":"Ge'ez","lat":15.3359,"lon":38.9266,"speakers":9900000,"region":"Africa","samples":["ብመንፅር ክብርን መሰልን ኩሎም ሰባት እንትውለዱ ነፃን ማዕሪን እዮም፡፡ ምስትውዓልን ሕልናን ዝተዓደሎም ብምዃኖም ንሕድሕዶም ብሕውነታዊ መንፈስ ክተሓላለዩ ኦለዎም፡፡","ሕድሕድ ሰብ ብህይወት ናይ ምንባር፣ ናይ ነፃነትን ድሕንነትን መሰል ኦለዎ፡፡","ሕድሕድ ሰብ ብሕጊ ካብ ዝተደንገገ ስርዓት ወፃኢ ኦይእሰርን፣ ኦይተሓዝን ወይ ኦይሕየርን፡፡"],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_tir.xml","speakers":"https://en.wikipedia.org/wiki/Tigrinya_language","glottolog":"https://glottolog.org/resource/languoid/id/tigr1271"}},{"name":"Somali","aka":["Af-Soomaali"],"family":"Afro-Asiatic","branch":"Cushitic","script":"Latin","lat":4.7787,"lon":45.1529,"speakers":24000000,"region":"Africa","samples":["Aadanaha dhammaantiis wuxuu dhashaa isagoo xor ah kana siman xagga sharafta iyo xuquuqada Waxaa Alle (Ilaah) siiyay aqoon iyo wacyi, waana in qof la arkaa qofka kale ula dhaqmaa si walaaltinimo ah.","Qof kastaa wuxuu xaq u leeyahay nolol, xorriyo iyo nabad gelyo.","Ma jiro qof loo geysan karo silic dilyo ama ciqaab ka baxsan aadaninimada."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_som.xml","speakers":"https://en.wikipedia.org/wiki/Somali_language","glottolog":"https://glottolog.org/resource/languoid/id/soma1255"}},{"name":"Oromo","aka":["Afaan Oromoo"],"family":"Afro-Asiatic","branch":"Cushitic","script":"Latin","lat":8.8139,"lon":36.7365,"speakers":45500000,"region":"Africa","samples":["Namooti hundinuu birmaduu ta'anii mirgaa fi ulfinaanis wal-qixxee ta'anii dhalatan. Sammuu fi qalbii ittiin yaadan waan uumamaan kennameef, hafuura obbolummaatiin walii-wajjin jiraachuu qabu.","Namni kamiyyuu mirga jiraachuu, birmadummaa argachuu fi mirga qaamni isaa eegamuu ni qaba.","Namni kamiyyuu garmalee hin hidhamu, biyyaas hin ari'atamu."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_gax.xml","speakers":"https://en.wikipedia.org/wiki/Oromo_language","glottolog":"https://glottolog.org/resource/languoid/id/west2721"}},{"name":"Shona","aka":["chiShona"],"family":"Atlantic-Congo","branch":"Bantu","script":"Latin","lat":-17.2085,"lon":29.7572,"speakers":9600000,"region":"Africa","samples":["Vanhu vese vanoberekwa vakasununguka uyewo vakaenzana pahunhu nekodzero dzavo. Vanhu vese vanechipo chokufunga nekuziva chakaipa nechakanaka saka vanofanira kubatana nomweya wohusahwira.","Munhu wese anekodzero yokurarama, kuvanerusununguko nokuzvichengetedza iye omene.","Hapana munhu achasungwa, kupfigirwa mutorongo kana kudzingwa munyika make zvisiri pamutemo."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_sna.xml","speakers":"https://en.wikipedia.org/wiki/Shona_language","glottolog":"https://glottolog.org/resource/languoid/id/shon1251"}},{"name":"Kinyarwanda","aka":["Rwanda","Ikinyarwanda"],"family":"Atlantic-Congo","branch":"Bantu","script":"Latin","lat":-1.5677,"lon":29.6441,"speakers":15000000,"region":"Africa","samples":["Abantu bose bavuka aliko bakwiye agaciro no kwubahwa kimwe. Bose bavukana ubwenge n'umutima, bagomba kugilirana kivandimwe.","Umuntu wese agomba kubaho, gushyira akizana no kutarengana.","Aho umuntu ali hose agomba kurengerwa n'amategeko y'igihugu."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_kin.xml","speakers":"https://en.wikipedia.org/wiki/Kinyarwanda","glottolog":"https://glottolog.org/resource/languoid/id/kiny1244"}},{"name":"Kirundi","aka":["Rundi","Ikirundi"],"family":"Atlantic-Congo","branch":"Bantu","script":"Latin","lat":-2.94,"lon":29.97,"speakers":13000000,"region":"Africa","samples":["Abantu bose bavuka bishira bakizana kandi bangana mu gateka no mu ngingo zibubahiriza. Bafise ubwenge n'umutima kandi bategerezwa kwubahana nk'abavandimwe.","Umuntu wese ategerezwa kwubahirizwa n'ugukingirwa mu buzima bwiwe, akishira akizana.","Umuntu wese ategerezwa kwubahwa akubahirizwa aho ari hose."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_run.xml","speakers":"https://en.wikipedia.org/wiki/Kirundi","glottolog":"https://glottolog.org/resource/languoid/id/rund1242"}},{"name":"Luganda","aka":["Ganda"],"family":"Atlantic-Congo","branch":"Bantu","script":"Latin","lat":0.6688,"lon":32.1515,"speakers":5600000,"region":"Africa","samples":["Abantu bazaalibwa nga balina eddembe n'obuyinza ebyenkanankana, batondebwa nga balina amagezi era nga basobola okwawula ekirungi n'ekibi bwebatyo, buli omu agwana okuyisa munne nga muganda we.","Buli muntu ateekwa okubeerawo nga mulamu nga yegazaanya awatali kutaataganyizibwa mu ngeri yonna.","Buli muntu amateeka gateekwa okumubala era n'okumuyisa ng'omuntu buli wantu wonna."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_lug.xml","speakers":"https://en.wikipedia.org/wiki/Luganda","glottolog":"https://glottolog.org/resource/languoid/id/gand1255"}},{"name":"Lingala","aka":["Lingála"],"family":"Atlantic-Congo","branch":"Bantu","script":"Latin","lat":-4.4092,"lon":15.2853,"speakers":21000000,"region":"Africa","samples":["Bato nyonso na mbotama bazali nzomi pe bakokani na limemya pe makoki. Bazali na mayele pe basengeli kofanda na bondeko okati na bango.","Moto nyonso azali na likoki ya kozala na bomoi, a kozala somi pe kozala motema sei na bomoto na ye.","Moto moko te akoki kokangama to kobengisama tina te."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_lin.xml","speakers":"https://en.wikipedia.org/wiki/Lingala","glottolog":"https://glottolog.org/resource/languoid/id/ling1263"}},{"name":"Wolof","aka":[],"family":"Atlantic-Congo","branch":"Atlantic","script":"Latin","lat":15.2534,"lon":-15.383,"speakers":8200000,"region":"Africa","samples":["Doomi aadama yépp danuy juddu, yam ci tawfeex ci sag ak sañ-sañ. Nekk na it ku xam dëgg te ànd na ak xelam, te war naa jëflante ak nawleen, te teg ko ci wàllu mbokk.","Nit kune war naa dund ci tawfeex ak kaaraange.","Menuñoo jàpp, tëj, mbaa genne kenn réewam te tegunu ko ci yoon."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_wol.xml","speakers":"https://en.wikipedia.org/wiki/Wolof_language","glottolog":"https://glottolog.org/resource/languoid/id/nucl1347"}},{"name":"Pular","aka":["Fula","Fulani","Fulfulde","Fula (Pular)"],"family":"Atlantic-Congo","branch":"Atlantic","script":"Latin","lat":12.1826,"lon":-12.7338,"speakers":4800000,"region":"Africa","samples":["NEDDHANKE EN FOW DYIBINTE NO HETTII NO FOTA E DHI FOW, E NDIMU E HANDANDHI. BHE DYIBINDINTE E HAGGHIL E FAAMU ; HIBHE HAANI DYOGONDIRDE E NDER HAGGHIL NEENEGOOTAANKAAKU.","KALA NEDDHO NO HANNDI E GURDAN, HETTAARE E HOOLORDE DADHUGOL.","KALA NO HANNDI ANDITANEEDE NOKKU FOW NDIMANKAAKU MUN."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_fuf.xml","speakers":"https://en.wikipedia.org/wiki/Pular_language","glottolog":"https://glottolog.org/resource/languoid/id/pula1262"}},{"name":"Bambara","aka":["Bamanankan"],"family":"Mande","branch":"Western Mande","script":"Latin","lat":12.9,"lon":-7.65,"speakers":4200000,"region":"Africa","samples":["Hadamaden bɛɛ danmakɛɲɛnen bɛ bange, danbe ni josira la. Hakili ni taasi b’u bɛɛ la, wa u ka kan ka badenɲasira de waleya u ni ɲɔgɔn cɛ.","Hadamaden bɛɛ ka kan ni kisi ni tanga ni hɔrɔɲa ye.","Mɔgɔ bɛɛ ka kan ni jateli ye sariya fɛ yɔrɔ bɛɛ."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_bam.xml","speakers":"https://en.wikipedia.org/wiki/Bambara_language","glottolog":"https://glottolog.org/resource/languoid/id/bamb1269"}},{"name":"Twi","aka":["Akan","Asante Twi"],"family":"Atlantic-Congo","branch":"Kwa","script":"Latin","lat":6.3476,"lon":-1.3325,"speakers":null,"region":"Africa","samples":["Nnipa nyinaa yɛ pɛ. Na wɔde adwene ne nyansa na abɔ obiara. Ɛno nti, ɛsɛ sɛ obiara dɔ ne yɔnko, bu ne yɔnko, di ne yɔnko ni.","Obiara wɔ ho kwan sɛ ɔtena ase asomdwoeɛ ne ahofadie mu a bɔne biara nka ne nipadua no.","Sɛ obiara kɔpue mmara anim wɔ baabiara a, ɛsɛ sɛ wɔgye no to mu sɛ onipa."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_aka_asante.xml","speakers":"https://en.wikipedia.org/wiki/Twi","glottolog":"https://glottolog.org/resource/languoid/id/twii1234"}},{"name":"Ewe","aka":["Eʋegbe"],"family":"Atlantic-Congo","branch":"Kwa","script":"Latin","lat":6.4606,"lon":0.815,"speakers":5000000,"region":"Africa","samples":["Wodzi amegbetɔwo katã ablɔɖeviwoe eye wodzena bubu kple gomekpɔkpɔ sɔsɔe. Susu kple dzitsinya le wo dometɔ ɖesiaɖe si eyata wodze be woanɔ anyi le ɖekawɔwɔ blibo me.","Ele be amesiame nanɔ agbe leablɔɖe kple dedienɔnɔ me.","Woade bubu amesiame ŋu le afisiafi abe amegbetɔ ene le se la nu."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_ewe.xml","speakers":"https://en.wikipedia.org/wiki/Ewe_language","glottolog":"https://glottolog.org/resource/languoid/id/ewee1241"}},{"name":"Fon","aka":["Fongbe"],"family":"Atlantic-Congo","branch":"Kwa","script":"Latin","lat":7.1548,"lon":1.6649,"speakers":2300000,"region":"Africa","samples":["Acɛ, susu kpo sisi ɖokpo ɔ kpo wɛ gbɛtɔ bi ɖo ɖò gbɛwiwa tɔn hwenu; ye ɖo linkpɔn bɔ ayi yetɔn mɛ kpe lo bɔ ye ɖo na do alɔ yeɖee ɖi nɔvinɔvi ɖɔhun.","Gbɛtɔ ɖokpoɖokpo ɖo na mɔ gbɛ bo nɔ eɖesu si lo bo na lɛ nyi eɖee.","Gbɛtɔ ɔ nusisi wɛ ɖo na nyi ɖo fi bi."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_fon.xml","speakers":"https://en.wikipedia.org/wiki/Fon_language","glottolog":"https://glottolog.org/resource/languoid/id/fonn1241"}},{"name":"Malagasy","aka":[],"family":"Austronesian","branch":"Malayo-Polynesian","script":"Latin","lat":-19.5907,"lon":47.1211,"speakers":25000000,"region":"Africa","samples":["Teraka afaka sy mitovy zo sy fahamendrehana ny olombelona rehetra. Samy manan-tsaina sy fieritreretana ka tokony hifampitondra am- pirahalahiana.","Manana zo hiaina, ho afaka, hahazo fiarovana ny olona tsirairay.","Tsy misy olona azo samborina tsy amin'antony na tazonim-poana na atao sesi-tany tsy voameloka."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_plt.xml","speakers":"https://en.wikipedia.org/wiki/Malagasy_language","glottolog":"https://glottolog.org/resource/languoid/id/plat1254"}},{"name":"Chichewa","aka":["Nyanja","Chewa"],"family":"Atlantic-Congo","branch":"Bantu","script":"Latin","lat":-14.8047,"lon":32.8108,"speakers":7000000,"region":"Africa","samples":["Anthu onse amabadwa aufulu ndiponso ofanana mu ulemu ndi ufulu wao. Iwowa ndi wodalitsidwa ndi mphamvu zoganiza ndi chikumbumtima ndipo achitirane wina ndi mnzake mwaubale.","Aliyense ali ndi ufulu kukhala ndi moyo, mtendere ndi chitetezo chathupi.","Aliyense ali ndi ufulu kuzindikiridwa ngati munthu kulikonse pamaso pa lumulo."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_nya_chechewa.xml","speakers":"https://en.wikipedia.org/wiki/Chewa_language","glottolog":"https://glottolog.org/resource/languoid/id/nyan1308"}},{"name":"Sesotho","aka":["Southern Sotho"],"family":"Atlantic-Congo","branch":"Bantu","script":"Latin","lat":-28.78,"lon":27.89,"speakers":5600000,"region":"Africa","samples":["Batho bohle ba tswetswe ba lokolohile mme ba lekana ka botho le ditokelo. Ba tswetswe le monahano le letswalo mme ba tlamehile ho phedisana le ba bang ka moya wa boena.","Motho e mong le e mong o na le tokelo ya ho phela, ya bolokolohi le ya paballo ya botho ba hae.","Ha ho motho ya tla tshwarwa feelafeela, a kwallwe kapa a lelekwe naheng."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_sot.xml","speakers":"https://en.wikipedia.org/wiki/Sotho_language","glottolog":"https://glottolog.org/resource/languoid/id/sout2807"}},{"name":"Tswana","aka":["Setswana"],"family":"Atlantic-Congo","branch":"Bantu","script":"Latin","lat":-24.368,"lon":24.7587,"speakers":5200000,"region":"Africa","samples":["Batho botlhe ba tsetswe ba gololosegile le go lekalekana ka seriti le ditshwanelo. Ba abetswe go akanya le maikutlo, mme ba tshwanetse go direlana ka mowa wa bokaulengwe.","Mongwe le mongwe o na le tshwanelo ya botshelo, boithatelo le tshireletsego ya botho.","Ga go ope yo o ka tshwarwang, a tlhatlhelwa kgotsa a kobiwa ntle le lebaka le le utlwalang."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_tsn.xml","speakers":"https://en.wikipedia.org/wiki/Tswana_language","glottolog":"https://glottolog.org/resource/languoid/id/tswa1253"}},{"name":"Tsonga","aka":["Xitsonga"],"family":"Atlantic-Congo","branch":"Bantu","script":"Latin","lat":-23.5754,"lon":31.8105,"speakers":3700000,"region":"Africa","samples":["Vanhu hin'kwavu va psaliwili na va khululekìle, funthsi va fana hi lisima ni tinfaneno. Và psaliwili ni nyiko ya ku pimisa ni ku yehleketa; hi kolahu, va fanela ku hanya hi moya wa umbìlu ni unghani.","Munhu ni munhu à ni nfanelo ya wutòmi, nkhululeko ni usirhelèli.","Wihi na wihi à ni nfanelo ya kuhloniphiwa svanga munhu phambhèni ka nawu."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_tso_MZ.xml","speakers":"https://en.wikipedia.org/wiki/Tsonga_language","glottolog":"https://glottolog.org/resource/languoid/id/tson1249"}},{"name":"Bemba","aka":["Chibemba"],"family":"Atlantic-Congo","branch":"Bantu","script":"Latin","lat":-10.6122,"lon":29.2993,"speakers":4100000,"region":"Africa","samples":["Abantu bonse bafyalwa abalubuka nokulingana mu mucinshi nensambu. Balikwata amano nokutontonkanya, eico bafwile ukulacita ifintu ku banabo mu mutima wa bwananyina.","Cila muntu alikwata insabu ya mweo, ukucita ico alefwaya elyo noku icingilila umwine.","Onse alikwata insambu ukwishibikwa ukuli konse ngo muntu pa menso ya cilye."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_bem.xml","speakers":"https://en.wikipedia.org/wiki/Bemba_language","glottolog":"https://glottolog.org/resource/languoid/id/bemb1257"}},{"name":"Kikongo","aka":["Kongo","Koongo"],"family":"Atlantic-Congo","branch":"Bantu","script":"Latin","lat":-5.5772,"lon":14.4771,"speakers":6000000,"region":"Africa","samples":["Bantu nyonso, na mbutukulu kevwandaka na kimpwanza ya bawu, ngenda mpe baluve ya mutindu mosi. Mayela na mbanzulu je na bawu, ni yawu yina bafwana kusalasana na bumpangi.","Konso muntu ke na luve ya kuzinga, ya kuvwanda na kimpwanza mpe ya kuvwanda na kizunu ya bumumtu ya yandi.","Muntu muntu ke na baluve kisika ni kisika yandi kele."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_kng.xml","speakers":"https://en.wikipedia.org/wiki/Kongo_language","glottolog":"https://glottolog.org/resource/languoid/id/koon1244"}},{"name":"Makhuwa","aka":["Makua","Emakhuwa"],"family":"Atlantic-Congo","branch":"Bantu","script":"Latin","lat":-14.8509,"lon":38.8052,"speakers":8600000,"region":"Africa","samples":["Atthu othene aniyaria oolikana ni owilamula moota ontthunaya okhala, variyari v’edignidade ni edireito. Akhalanne esaria ni otthokelela, ahaana akhalasaka othene saya vamurettele.","Wakunla pinatamu ohaana edireito ya ekumi, eliberdade ni wakiha erutthu awe.","Khavo onrowa ohoosiwa, nnakhala okhalihiwa moota wonanara."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_vmw.xml","speakers":"https://en.wikipedia.org/wiki/Makhuwa_language","glottolog":"https://glottolog.org/resource/languoid/id/makh1264"}},{"name":"Sango","aka":[],"family":"Atlantic-Congo","branch":"Ubangian","script":"Latin","lat":6.7858,"lon":20.1702,"speakers":620000,"region":"Africa","samples":["Adü âzo kûê yamba, ngâ âla lîngbi terê na lêgë tî nëngö-terê na tî ângangü. Ala kûê awara ndarä na börö-li sï âla lîngbi tî dutï na âmbâ tî âla gï na lêngö söngö.","Zo kûê ayeke na ngangü tî dutï na finî tî lo, tî dutï yamba na tî dutï na mbeto tî wara sïönî pëpëe.","Zo kûê ayeke na ngangü tî tene ndiä abata lo na âsïönî lâkûê na ndo kûê."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_sag.xml","speakers":"https://en.wikipedia.org/wiki/Sango_language","glottolog":"https://glottolog.org/resource/languoid/id/sang1328"}},{"name":"Standard Moroccan Tamazight","aka":["Berber","Tamazight","ⵜⴰⵎⴰⵣⵉⵖⵜ"],"family":"Afro-Asiatic","branch":"Berber","script":"Tifinagh","lat":32.7415,"lon":-2.4087,"speakers":null,"region":"Africa","samples":["ⴰⵔ ⴷ ⵜⵜⵍⴰⵍⴰⵏ ⵎⵉⴷⴷⵏ ⴳⴰⵏ ⵉⵍⴻⵍⵍⵉⵜⵏ ⵎⴳⴰⴷⴷⴰⵏ ⵖ ⵡⴰⴷⴷⵓⵔ ⴷ ⵉⵣⵔⴼⴰⵏ, ⵢⵉⵍⵉ ⴰⴽⵯ ⴷⴰⵔⵙⵏ ⵓⵏⵍⵍⵉ ⴷ ⵓⴼⵔⴰⴽ, ⵉⵍⵍⴰ ⴼⵍⵍⴰ ⵙⵏ ⴰⴷ ⵜⵜⵎⵢⴰⵡⴰⵙⵏ ⵏⴳⵔⴰⵜⵙⵏ ⵙ ⵜⴰⴳⵎⴰⵜ.","ⴽⵓ ⵢⴰⵏ ⵉⵍⵍⴰ ⴷⴰⵔⵙ ⵓⵣⵔⴼ ⵖ ⵜⵓⴷⵔⵜ ⴷ ⵜⴷⵔⴼⵉⵜ ⴷ ⵜⵏⴼⵔⵓⵜ ⵜⴰⵏⵉⵎⴰⵏⵜ.","ⴽⵓ ⵢⴰⵏ ⵉⵍⵍⴰ ⴷⴰⵔⵙ ⵓⵣⵔⴼ ⵏ ⵜⵓⴽⵣⴰ ⵏ ⵉⵎⴰⵏ ⵏⵙ ⴰⵣⵔⴼⴰⵏ ⵖ ⴽⴰⵢⴳⴰⵜ ⴰⴷⵖⴰⵔ."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_zgh.xml","speakers":"https://en.wikipedia.org/wiki/Standard_Moroccan_Amazigh","glottolog":"https://glottolog.org/resource/languoid/id/stan1324"}},{"name":"Kabyle","aka":["Taqbaylit","Berber"],"family":"Afro-Asiatic","branch":"Berber","script":"Latin","lat":36.4103,"lon":4.7614,"speakers":4000000,"region":"Africa","samples":["Imdanen akken ma llan ttlalen-d d ilelliyen gdan deg lḥeṛma d yizerfan , ɣur-sen leɛqel d tefrit, yessefk ad tili tegmat gar-asen.","Yal amdan ɣur-s azref n tudert, tilelli d teɣlist ɣef yiman-is.","Yal amdan ɣur-s azref ad tettwaqader tugna-ines tazerfant."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_071.xml","speakers":"https://en.wikipedia.org/wiki/Kabyle_language","glottolog":"https://glottolog.org/resource/languoid/id/kaby1243"}},{"name":"Tiv","aka":[],"family":"Atlantic-Congo","branch":"Tivoid","script":"Latin","lat":6.8804,"lon":9.2629,"speakers":4600000,"region":"Africa","samples":["I mar maor ken kpan ga, nan ngu a icivir man mbamkpeiyol cii. I na nan mhen man ishima i kaven kwagh; nahan gba keng u nana tema a orgen ken mtem u angbian a angbian.","Hanmaor nan ngu a ian u lun uma, eren kwagh a mkighir shio man mkor u sha iyol i nan kpaa.","Hanmaor nan ngu a ian u hanma ijiir cii yô, i er kwagh a nan sha er tindi a tese er i eren a orumace la vough."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_tiv.xml","speakers":"https://en.wikipedia.org/wiki/Tiv_language","glottolog":"https://glottolog.org/resource/languoid/id/tivv1240"}},{"name":"Mossi","aka":["Mooré","Mòoré"],"family":"Atlantic-Congo","branch":"Gur","script":"Latin","lat":11.95,"lon":-1.32,"speakers":12000000,"region":"Africa","samples":["Ninsaalbã fãa sã n doge, ned fãa so a menga, ned pa rogd n yaa yamb ye, nebã fãa zema taab b yel-segdɩ la b burkĩndlem wɛɛngẽ. Nebã fãa tara yam la tagsgo, ned fãa togame n vɩɩnd ne a to saam-biir pʊgẽ.","Ned buud fãa tara sor n tõe n vɩɩnde, n soog a menga la a gũnug a menga.","Ned fãa tara sor tɩ sẽn wa n ya sĩĩg ning fãa, bɩ b sak n deeg a sẽn yaa ned ning buud bʊ-kaoor soog taoore."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_mos.xml","speakers":"https://en.wikipedia.org/wiki/Moor%C3%A9","glottolog":"https://glottolog.org/resource/languoid/id/moss1236"}},{"name":"Dinka","aka":[],"family":"Nilotic","branch":"Western Nilotic","script":"Latin","lat":9.2799,"lon":31.8392,"speakers":4200000,"region":"Africa","samples":["Raan thök eben aye dhëëth ka lau nhöm kua thöŋ nhiim eyithiic, kua thɛ̈kic, kua ci yëknhiethku puou, ku bik cëŋ ka ke ye mith etik.","Raan thök eben alɛŋ yic bi pir ku leu nhöm ku le laŋ.","Ran thok eben aci leu bi döm kemen dampiny, kemen cöb ewëi baai edieny."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_dip.xml","speakers":"https://en.wikipedia.org/wiki/Dinka_language","glottolog":"https://glottolog.org/resource/languoid/id/nort2815"}},{"name":"Krio","aka":[],"family":"Indo-European","branch":"Germanic","script":"Latin","lat":10.8811,"lon":-14.3204,"speakers":860000,"region":"Africa","samples":["ɛvribɔdi bɔn fri ɛn gɛt in yon rayt, nɔn wan nɔ pas in kɔmpin. Wi ɔl ebul fɔ tink ɛn fɛnɔt wetin rayt ɛn rɔŋ pantap dat wi fɔ sabi aw fɔ liv lɛk wan big famili.","Evribɔdi fɔ ebul fɔ liv in layf, fɔ fil fri ɛn fɔ fil sɛf se nɔbɔdi ɔ natin nɔ go denja in layf.","Nɔbɔdi nɔ fɔ mek in kɔmpin in slev – dis, ɔɛnitiŋ sɛf we fiba am fɔ tap."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_kri.xml","speakers":"https://en.wikipedia.org/wiki/Krio_language","glottolog":"https://glottolog.org/resource/languoid/id/krio1253"}},{"name":"Cape Verdean Creole","aka":["Kabuverdianu"],"family":"Indo-European","branch":"Romance","script":"Latin","lat":15.0586,"lon":-23.6148,"speakers":871000,"region":"Africa","samples":["Tudo ser humano na ês mundo nacê libri e igual na sê dignidade e na sês drêto. Na sês razon e na sês concénça, tudo arguem debê porcêdê pa co tudo guenti na sprito di fraternidadi.","Tudo arguém tem drêto di sê bida, di tem liberdadi e, tem di tem sigurança di el própri.","Tudo homi di Deus tem drêto di ser conchido na tudo lugar di sê própri péssoa djusto tambê na cusas di tribunal."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_kea.xml","speakers":"https://en.wikipedia.org/wiki/Cape_Verdean_Creole","glottolog":"https://glottolog.org/resource/languoid/id/kabu1256"}},{"name":"Nigerian Pidgin","aka":["Naijá"],"family":"Indo-European","branch":"Germanic","script":"Latin","lat":9.6587,"lon":4.2107,"speakers":4700000,"region":"Africa","samples":["Everi human being, naim dem born free and dem de equal for dignity and di rights wey we get, as human beings, God come give us beta sense wey we de take tink well, well and beta mind, sake for dis, we must to treat each other like broda and sister.","Everi one naim get right to live, get right to do as e like and right to see say im life safe for where e dey.","Everi one na im get right say make dem know am anywhere say na person, sef, as a person before di law."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_pcm.xml","speakers":"https://en.wikipedia.org/wiki/Nigerian_Pidgin","glottolog":"https://glottolog.org/resource/languoid/id/nige1257"}},{"name":"Maasai","aka":["Maa"],"family":"Nilotic","branch":"Eastern Nilotic","script":"Latin","lat":-3.1419,"lon":36.4573,"speakers":1500000,"region":"Africa","samples":["Iyiolo iltung’anak pooki naa ketoiwuoki naa kenare enkishui o sipat. Naa kenare nikiyanyit irkulikae enaa ilalashera.","Keeta olosho pookin esipata enkishui,niidim aataas inaayieu, o sipat nemayiani.","Imenare nitayae oltung’ani ashu neeni tejela toorrkesin leitu ees."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_045.xml","speakers":"https://en.wikipedia.org/wiki/Maasai_language","glottolog":"https://glottolog.org/resource/languoid/id/masa1300"}},{"name":"Vai","aka":["ꕙꔤ"],"family":"Mande","branch":"Western Mande","script":"Vai","lat":7.0508,"lon":-11.3262,"speakers":120000,"region":"Africa","samples":["ꕉꕜꕮ ꔔꘋ ꖸ ꔰ ꗋꘋ ꕮꕨ ꔔꘋ ꖸ ꕎ ꕉꖸꕊ ꕴꖃ ꕃꔤꘂ ꗱ, ꕉꖷ ꗪꗡ ꔻꔤ ꗏꗒꗡ ꕎ ꗪ ꕉꖸꕊ ꖏꕎ. ꕉꕡ ꖏ ꗳꕮꕊ ꗏ ꕪ ꗓ ꕉꖷ ꕉꖸ ꕘꕞ ꗪ. ꖏꖷ ꕉꖸꔧ ꖏ ꖸ ꕚꕌꘂ ꗷꔤ ꕞ ꘃꖷ ꘉꔧ ꗠꖻ ꕞ ꖴꘋ ꔳꕩ ꕉꖸ ꗳ.","ꗞ ꔰ ꕚ ꖷ ꕉ ꔱꕩ ꗃꗡ ꕞ, ꗞ ꔰ ꔇꔀ ꕉ ꗃ ꗛꖺ ꗘꘋꕧ ꗏ ꕉꖷ ꗞ ꔰ ꖴꘋ ꕃꕞ ꗏꖺꕎ ꕉ ꕩꕌ ꕎꕬ ꖴꕮ ꗱꗡ.","ꕕ ꖷ ꗞ ꖸꔧ ꕀꔤ ꔻꔤ ꗞ ꔰ ꕞ ꕉꕜꕮ ꔔꘋꕧꕌ ꕮ ꕪꘋ ꔰ ꕢꕎꕌ ꕧꕌ."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_vai.xml","speakers":"https://en.wikipedia.org/wiki/Vai_language","glottolog":"https://glottolog.org/resource/languoid/id/vaii1241"}},{"name":"Quechua","aka":["Runasimi","Cusco Quechua"],"family":"Quechuan","branch":"Southern Quechua","script":"Latin","lat":-14.0853,"lon":-71.7663,"speakers":5000000,"region":"Americas","samples":["Llapa runan kay pachapi paqarin qispisqa, \"libre\" flisqa, allin kausaypi, chaninchasqa kausaypi kananpaq, yuyayniyoq, yachayniyoq runa kasqanman jina. Llapa runamasinwantaqmi wauqentin jina munanakunan.","Llapan runan kausaypachapaq kamasqa, mana piqpa rimapayasqantaqmi purikunan kausanan p 'unchaykama.","Llapa runaq \"derechunmi\", maypipas runa jina \"respetasqa\" kananpaq."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_quz.xml","speakers":"https://en.wikipedia.org/wiki/Southern_Quechua","glottolog":"https://glottolog.org/resource/languoid/id/cusc1236"}},{"name":"Aymara","aka":["Aymar aru"],"family":"Aymaran","branch":"Central-Southern Aymara","script":"Latin","lat":-17.0,"lon":-68.5,"speakers":1700000,"region":"Americas","samples":["Taqpach jaqejh khuskat uñjatatäpjhewa munañapansa, lurañapansa, amuyasiñapansa, ukatwa jilani sullkanípjhaspas ukham uñjasipjhañapawa.","Sapaqat jaqejh jan khitirus ajhsarasa jakañapa, munañapa, amuyasiñapa, jaqe kankañapa taqjhatasiñapaw.","Janirakiw taqe jaqenakat maynikis khuyaña mutuñanakampi chhojrinchatäñapati."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_ayr.xml","speakers":"https://en.wikipedia.org/wiki/Aymara_language","glottolog":"https://glottolog.org/resource/languoid/id/cent2142"}},{"name":"Guarani","aka":["Avañe'ẽ","Guaraní"],"family":"Tupian","branch":"Tupi-Guarani","script":"Latin","lat":-25.6055,"lon":-57.0882,"speakers":6500000,"region":"Americas","samples":["Mayma yvypóra ou ko yvy ári iñapytlʼyre ha eteĩcha dignidad ha derecho jeguerekópe; ha ikatu rupi oikuaa añetéva ha añeteʼyva, iporãva ha ivaíva, tekotevẽ pehenguéicha oiko oñondivekuéra.","Mayma tapicha oguereko derecho oikovévo, piporúvo ilibertad ha ojerrespetávo ipersona.","Avavére ndoikovaʼerãi ñembosarái vai térã ñambohasa asy, humano rekore ndojojáiva."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_gug.xml","speakers":"https://en.wikipedia.org/wiki/Guarani_language","glottolog":"https://glottolog.org/resource/languoid/id/para1311"}},{"name":"Nahuatl","aka":["Nāhuatl","Aztec"],"family":"Uto-Aztecan","branch":"Aztec (Nahuan)","script":"Latin","lat":19.1248,"lon":-98.3002,"speakers":1700000,"region":"Americas","samples":["Nochi tlakamej uan siuamej kipiaj manoj kuali tlakatisej, nochi san se totlatechpouiltilis uan titlatepanitalojkej, yeka moneki kuali ma timouikakaj, ma timoiknelikaj, ma timotlasojtlakaj uan ma timotlepanitakaj.","Nochi tlakamej uan siuamej kipiaj manoj kuali itstosej, amo akaj ma se kinixpano, kipiaj manoj nemisej kampa inijuantij kinekisej uan amo uelis tlen impantis.","Amo onkaj manoj ma se akajya techtlatsakuilti para ma tikijtokaj o ma tijchiuakaj se tleueli tlamantli tlen amo tijnekij tikijtosej pampa amo melauak."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_nhn.xml","speakers":"https://en.wikipedia.org/wiki/Nahuatl","glottolog":"https://glottolog.org/resource/languoid/id/cent2132"}},{"name":"Yucatec Maya","aka":["Maya","Màaya t'àan"],"family":"Mayan","branch":"Yucatecan","script":"Latin","lat":18.7757,"lon":-88.9567,"speakers":800000,"region":"Americas","samples":["Tuláakal wíinik ku síijil jáalkʼab yetel keet u tsiikul yetel Najmal Sijnalil, beytun xan naʼataʼan sijnalil yetel noʼojaʼanil u tuukuloʼ, kʼaʼabet u bisikuba bey láaktzilil yetel tuláakal u baatzileʼ.","Tuláakal wíinikeʼ Sijnal u Najmalmajil u kuxtal, maʼ u palitziltaʼal beeyxan maʼ u loʼobol u wíinklal yetel u kaalantaʼal u kuxtal.","Mixmáak unaj u kʼaʼalal wa maʼa u káant yetel u kʼam u siʼipiliʼ, mix u tojolchʼintaʼal tu kaajal."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_yua.xml","speakers":"https://en.wikipedia.org/wiki/Yucatec_Maya_language","glottolog":"https://glottolog.org/resource/languoid/id/yuca1254"}},{"name":"K'iche'","aka":["Quiché"],"family":"Mayan","branch":"Quichean","script":"Latin","lat":14.5278,"lon":-91.1696,"speakers":1100000,"region":"Americas","samples":["Konojel ri winaq are taq ke'alaxik pa junaman ya'tal chkech kakechab'ej ronojel ri utzil; utz kakib'ano, kakichomaj, kakib'ij jasa je' ri k'o pa kanima, rumal che ri junam kib'antajik. Rajawaxik xuqe' kakimulij kib' che utzukuxuk ri loq'ob'al pa we uwachulew.","Ronojel winaq are taq kalax pa we uwachulew, ya'tal chech kuriq utzwachil pa ronojel uk'aslemal, ya'tal chech kub'ano jachke taq ri utz kab'anik; xuquje' ya'tal chech kachajixik, ka'ilix pa ri uk'aslemal rumal taq ri q'atb'altzij.","Maj jun winaq ya'tal ta chech koksax chwa ri nimaq taq ch'ay, che ri man rech ta winaq, jacha ne' we karapaxik."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_quc.xml","speakers":"https://en.wikipedia.org/wiki/K%CA%BCiche%CA%BC_language","glottolog":"https://glottolog.org/resource/languoid/id/kich1262"}},{"name":"Mapudungun","aka":["Mapuche"],"family":"Araucanian","branch":null,"script":"Latin","lat":-38.7392,"lon":-71.277,"speakers":410000,"region":"Americas","samples":["Kom pu mogence kisuzuam mvlekey, kom cegeygvn, logkogeygvn ka piwkegeygvn, nieygvn kimvn fey mew mvley tañi yamniewael ka epuñpvle kejuwael egvn.","Kom ce mvley ñi mogeleael, kisugvnew feleael ka yamniegeael.","Cem ce rume wezakamekegelayay, kupafkamekegelayay."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_arn.xml","speakers":"https://en.wikipedia.org/wiki/Mapudungun","glottolog":"https://glottolog.org/resource/languoid/id/mapu1245"}},{"name":"Navajo","aka":["Diné bizaad"],"family":"Athabaskan-Eyak-Tlingit","branch":"Athabaskan","script":"Latin","lat":36.33,"lon":-109.38,"speakers":170000,"region":"Americas","samples":["Bilaʼashdaʼii tʼáá ałtsoh yiníkʼehgo bidizhchįh dóó aheełtʼeego ílį́į́go bee baahóchįʼ. Eíí háníʼ dóó hánítshakees hwiihdaasyaʼ eíí binahjį́ʼ ahidiníłnáhgo álíleekʼehgo kʼé bee ahił niidlį́.","Tsídí tʼáá ájítʼé bee háhazʼą́ iináʼázhdoolííłgo áádóó ʼałdó tʼáá yiní kʼehgo hołdzilgo hołhazʼą́ądoo.","Tʼáá heíída éí doo atídoolníiłda áádóó ʼałdóʼ doo tʼáá naʼníleʼdii diné doo ídlį́į́go baa tsehodidookosda."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_nav.xml","speakers":"https://en.wikipedia.org/wiki/Navajo_language","glottolog":"https://glottolog.org/resource/languoid/id/nava1243"}},{"name":"Cherokee","aka":["ᏣᎳᎩ","Tsalagi"],"family":"Iroquoian","branch":null,"script":"Cherokee","lat":35.4664,"lon":-83.163,"speakers":1520,"region":"Americas","samples":["Ꮒꭶꮣ ꭰꮒᏼꮻ ꭴꮎꮥꮕꭲ ꭴꮎꮪꮣꮄꮣ ꭰꮄ ꭱꮷꮃꭽꮙ ꮎꭲ ꭰꮲꮙꮩꮧ ꭰꮄ ꭴꮒꮂ ꭲᏻꮎꮫꮧꭲ. Ꮎꮝꭹꮎꮓ ꭴꮅꮝꭺꮈꮤꮕꭹ ꭴꮰꮿꮝꮧ ꮕᏸꮅꮫꭹ ꭰꮄ ꭰꮣꮕꮦꮯꮣꮝꮧ ꭰꮄ ꭱꮅꮝꮧ ꮟᏼꮻꭽ ꮒꮪꮎꮣꮫꮎꮥꭼꭹ ꮎ ꮧꮎꮣꮕꮯ ꭰꮣꮕꮩ ꭼꮧ.","Ꮒꭶꮫ ꭰꮒᏼꮻ ꭴꮒꮂ ꮎꮝꭹ ꮪᏻꭺꮫ ᏻꮎꮫꮧꭲ ꭵꮄꮒꮩꮂꭲ, ꭳꭶꮣꮴꮅ ꭸꮢꭲ ꭰꮄ ꮎꮝꭹ ꭴꭶꮞꮝꮧ ᏼꮻ.","Ꮒꭶꮫ ꭰꮒᏼꮻ ꭴꮒꮂ ꮎꮝꭹ ꮪᏻꭺꮫ ꭲᏻꮎꮫꮑꮧꭲ ꮒꭼꮎꮫ ꭸꭺꮅꮴꮧ ꮎꮝꭹ ᏼꮻ ꭲꭼꮿꮨꮯ ꮎꮝꭹ ꮧꭷꮓꮹꮫꮝꮧ."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_chr_cased.xml","speakers":"https://en.wikipedia.org/wiki/Cherokee_language","glottolog":"https://glottolog.org/resource/languoid/id/cher1273"}},{"name":"Inuktitut","aka":["ᐃᓄᒃᑎᑐᑦ"],"family":"Eskimo-Aleut","branch":"Inuit","script":"Canadian Aboriginal Syllabics","lat":62.1735,"lon":-75.6139,"speakers":38000,"region":"Americas","samples":["ᐃᓅᔪᓕᒫᑦ ᐊᓂᖅᑎᕆᔪᓕᒫᑦ ᐃᓅᓚᐅᕐᒪᑕ ᐃᓱᒪᕐᓱᕐᖢᑎᒃ ᐊᒻᒪᓗ ᐊᔾᔨᐅᖃᑎᒌᒃᖢᑎᒃ ᓂᕐᓱᐊᖑᓂᒃᑯᑦ ᐊᒻᒪᓗ ᐱᔪᓐᓇᐃᑎᑎᒍᑦ. ᐃᓱᖃᖅᑐᖁᑎᖃᕐᑎᑕᐅᕙᓕᕐᐳᑦ ᐱᔾᔪᑎᖃᕐᓂᒃᑯᑦ ᖃᑕᙳᑎᒌᑦᑎᐊᕆᐊᖃᕐᓂᒃᑯᓪᓗ.","ᑭᓇᒃᑯᑐᐃᓐᓇᓕᒫᑦᑎᐊᑦ ᑕᒪᒃᑭᕐᖢᑎᒃ ᐱᔪᓐᓇᐅᑎᖃᕐᐳᑦ ᐃᓅᓯᕐᒥᓄᑦ, ᑭᓱᒡᒍᑎᖃᕆᐊᖃᕐᓂᖃᕋᓂ ᐃᓕᑕᕆᔭᐅᔾᔪᑎᒃᓴᒥᒃ ᐊᒻᒪᓗ ᒥᐊᓂᖅᓯᐅᑎᖃᕐᓂᒃᑯᑦ ᐃᓅᓯᖓᓄᑦ.","ᓴᒡᓗᕿᑦᓯᓂᒃᑯᑦ ᑎᒍᔭᐅᓂᖅᓗᒃᑎᑦᑎᔪᖃᖅᑐᒃᓴᐅᙱᓚᖅ, ᓱᑲᒃᑲᖓᓂᒃᑯᑦ ᐅᕝᕙᓘᓐᓃᑦ ᓄᓇᒥᖕᓂᑦ ᐊᓂᑎᑕᐅᔪᖃᖅᑐᒃᓴᐅᙱᓚᖅ."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_ike.xml","speakers":"https://en.wikipedia.org/wiki/Inuktitut","glottolog":"https://glottolog.org/resource/languoid/id/east2534"}},{"name":"Greenlandic","aka":["Kalaallisut"],"family":"Eskimo-Aleut","branch":"Inuit","script":"Latin","lat":69.3761,"lon":-52.864,"speakers":57000,"region":"Americas","samples":["Inuit tamarmik inunngorput nammineersinnaassuseqarlutik assigiimmillu ataqqinassuseqarlutillu pisinnaatitaaffeqarlutik. Solaqassusermik tarnillu nalunngissusianik pilersugaapput, imminnullu iliorfigeqatigiittariaqaraluarput qatanngutigiittut peqatigiinnerup anersaavani.","Kinaluunniit inuunermut, nammineersinnaassuseqarnissamut isumakuluuteqaranilu inuuniarnissamut pisinnaatitaavoq.","Kinaluunniit namminissarsiortumik tigusarineqassanngliq, tigummigallagassanngortitaassanani imaluunniit nunagisamit peersitaassanani."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_kal.xml","speakers":"https://en.wikipedia.org/wiki/Greenlandic_language","glottolog":"https://glottolog.org/resource/languoid/id/kala1399"}},{"name":"Mi'kmaq","aka":["Micmac"],"family":"Algic","branch":"Algonquian","script":"Latin","lat":46.0,"lon":-64.0,"speakers":7140,"region":"Americas","samples":["Msit mimajulnu’k weskwijinu’ltijik alsumsultijik aqq newte’ tett wkpimte’tmut aqq koqwajo’taqnn wejkul’aqmititl.","Msit wen wejkul’aqmit koqwajo’taqan wjit ta’n tel mimajij, teli-alsumsij aqq tel-sankewe’k wen.","Ma wen wskimtuk kisi-pija’luksik, kisna naqeyuksik kisna ejikleyuksik."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_mic.xml","speakers":"https://en.wikipedia.org/wiki/Mi'kmaq_language","glottolog":"https://glottolog.org/resource/languoid/id/mikm1235"}},{"name":"Ojibwe","aka":["Ojibwa","Anishinaabemowin"],"family":"Algic","branch":"Algonquian","script":"Canadian Aboriginal Syllabics","lat":51.6192,"lon":-87.7862,"speakers":50000,"region":"Americas","samples":["ᑭᑲᓇᐌᓀᓐ ᑲᐱᒪᑎᓯᐗᑦ ᓂᑕᐎᑭᐗᒃ ᑎᐯᓂᒥᑎᓱᐎᓂᒃ ᒥᓇ ᑕᐱᑕ ᑭᒋᐃᓀᑕᑯᓯᐎᓐ ᑲᔦ ᑌᐸᑫᑕᑯᓯᐎᓐ. ᐅᑕᔦᓇᐗ ᒥᑲᐎᐎᓐ ᑲᔦ ᓂᑄᑲᐎᓐ ᒥᓇᐗ ᑕᔥ ᒋᐃᔑᑲᓇᐗᐸᑎᐗᐸᓐ ᐊᒐᑯ ᒥᓄᐎᒋᐎᑎᐎᓂᒃ.","ᑲᑭᓇᐌᓀᓐ ᑌᐸᑫᑕᑯᓯ ᐱᒪᑎᓯᐎᓐ, ᒋᐊᐗᑲᓇᓯᐎᓐᑦ ᒥᓇ ᐊᔭᑾᒥᓯᐎᓂᒃ ᒋᐊᔭᒃ.","ᒥᓯᐌ ᐱᑯ ᐅᒪ ᑲᑭᓇᐌᓀᓐ ᑌᐸᑫᑕᑯᓯ ᒋᐃᔑᑭᑫᑕᑯᓯᑦ ᑲᐃᓇᓴᒥᓯᒃ ᐃᓇᑯᓂᑫᐎᓐ."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_ojb.xml","speakers":"https://en.wikipedia.org/wiki/Ojibwe_language","glottolog":"https://glottolog.org/resource/languoid/id/nort2961"}},{"name":"Cree","aka":["Swampy Cree","ᓀᐦᐃᔭᐍᐏᐣ"],"family":"Algic","branch":"Algonquian","script":"Canadian Aboriginal Syllabics","lat":56.0,"lon":-95.0,"speakers":86000,"region":"Americas","samples":["ᒥᓯᐌ ᐃᓂᓂᐤ ᑎᐯᓂᒥᑎᓱᐎᓂᐠ ᐁᔑ ᓂᑕᐎᑭᐟ ᓀᐢᑕ ᐯᔭᑾᐣ ᑭᒋ ᐃᔑ ᑲᓇᐗᐸᒥᑯᐎᓯᐟ ᑭᐢᑌᓂᒥᑎᓱᐎᓂᐠ ᓀᐢᑕ ᒥᓂᑯᐎᓯᐎᓇ᙮ ᐁ ᐸᑭᑎᓇᒪᒋᐠ ᑲᑫᑕᐌᓂᑕᒧᐎᓂᓂᐤ ᓀᐢᑕ ᒥᑐᓀᓂᒋᑲᓂᓂᐤ ᓀᐢᑕ ᐎᒋᑴᓯᑐᐎᓂᐠ ᑭᒋ ᐃᔑ ᑲᓇᐗᐸᒥᑐᒋᐠ᙮","ᒥᓯᐌ ᐊᐌᓇ ᐃᔑ ᒥᓂᑯᐎᓯᐤ ᑭᒋ ᐱᒪᑎᓯᐟ ᓀᐢᑕ ᑎᐯᓂᒥᑎᓱᐎᓂᓂᐤ ᓀᐢᑕ ᐁᑲ ᑭᒋ ᐅᒋ ᓇᓂᓴᓂᓯᐟ᙮","ᒥᓯᐌ ᐊᐌᓇ ᐁ ᑎᐸᑫᓂᑕᑯᓯᐟ ᑭᒋ ᓂᓯᑕᐌᓂᒥᐟ ᒥᓯᐌ ᐱᑯ ᑕᐢᑌ ᐁ ᐃᓂᓂᐎᐟ ᐅᑎᐢᑲᐤ ᐅᓇᔓᐌᐎᓂᐠ᙮"],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_csw.xml","speakers":"https://en.wikipedia.org/wiki/Cree_language","glottolog":"https://glottolog.org/resource/languoid/id/swam1239"}},{"name":"Haitian Creole","aka":["Kreyòl ayisyen"],"family":"Indo-European","branch":"Romance","script":"Latin","lat":18.7951,"lon":-72.1361,"speakers":13000000,"region":"Americas","samples":["Tout moun fèt lib, egal ego pou diyite kou wè dwa. Nou gen la rezon ak la konsyans epi nou fèt pou nou aji youn ak lot ak yon lespri fwatènite.","Chak moun gen dwa as ke li gen la vi, la libeète ak sekirite pou tèt-li.","Chak moun gen dwa as ke yo rekònet toupatou pèsonalite jiridik-li."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_hat_kreyol.xml","speakers":"https://en.wikipedia.org/wiki/Haitian_Creole","glottolog":"https://glottolog.org/resource/languoid/id/hait1244"}},{"name":"Jamaican Patois","aka":["Patwa","Jamaican Creole"],"family":"Indo-European","branch":"Germanic","script":"Latin","lat":18.13,"lon":-77.2612,"speakers":3200000,"region":"Americas","samples":["Evribadi baan frii an iikwal wid rispek fi demself (digniti) an wid raits. Dem nuo ou fi riizn kaa dem av sens an nuo we rait fram we rang (kanshenz) an dem fi chriit dem wan aneda laik se dem a breda an sista.","Evribadi av di rait fi liv, an fi bi frii an av kanchruol uova dem uona badi.","Evribadi evriwe av di rait az smadi we av akses tu di sorvis dem a di laa."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_055.xml","speakers":"https://en.wikipedia.org/wiki/Jamaican_Patois","glottolog":"https://glottolog.org/resource/languoid/id/jama1262"}},{"name":"Papiamento","aka":["Papiamentu"],"family":"Indo-European","branch":"Romance","script":"Latin","lat":12.4848,"lon":-69.9399,"speakers":350000,"region":"Americas","samples":["Tur ser humano ta nace liber y igual den dignidad y den derecho. Nan ta dota cu rason y cu consenshi y nan mester comporta nan den spirito di fraternidad pa cu otro.","Tur individuo tin derecho riba bida, riba libertad y riba seguridad di su persona.","Ningun hende lo no ta someti na aresto, detencion ni destiero arbitrario."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_pap.xml","speakers":"https://en.wikipedia.org/wiki/Papiamento","glottolog":"https://glottolog.org/resource/languoid/id/papi1253"}},{"name":"Miskito","aka":[],"family":"Misumalpan","branch":null,"script":"Latin","lat":15.1576,"lon":-84.2942,"speakers":150000,"region":"Americas","samples":["Upla sut ba kulkanka lakara, airaitka nanira bara pri, sin, aikuki, baku takisa. Bamna sins laka bri baku, lukanka bain pri baku aimuihni lakara, pana pana tabaikan kaiasa.","Upla sut ba airaitka brisa airayaka kum brieia pri lakara iwaia upla baku, aimain kira kaia.","Upla kumi sin, sip apia sa ban kakalhni silak ra mangki saura munaia."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_miq.xml","speakers":"https://en.wikipedia.org/wiki/Miskito_language","glottolog":"https://glottolog.org/resource/languoid/id/misk1235"}},{"name":"Wayuu","aka":["Wayuunaiki","Guajiro"],"family":"Arawakan","branch":"Caribbean Arawakan","script":"Latin","lat":11.3956,"lon":-72.1998,"speakers":420000,"region":"Americas","samples":["Naa wayuukana jemeishi süpüla taashi süma wanawa sülu'u nakua'ipa, aka müin yaa epijainjana sünain anajiranawaa a'in nama napüshi.","Naa wayuukana eeshi süpüla kajutüinjatüin atuma napülerua tüü kataakat o'u, tüü taashi jee müsüya a'inmajuna akua'ipa süulia kasachiki.","Noojolüinjachi ata'unüin wane wayuu masalajanoule."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_guc.xml","speakers":"https://en.wikipedia.org/wiki/Wayuu_language","glottolog":"https://glottolog.org/resource/languoid/id/wayu1243"}},{"name":"Shipibo-Conibo","aka":["Shipibo"],"family":"Pano-Tacanan","branch":"Panoan","script":"Latin","lat":-7.1711,"lon":-74.8219,"speakers":null,"region":"Americas","samples":["Jatíbi joninra huetsa jonibaon yoiai nincáresti iqui, jahueraquibi jaconmai iamaquin; jainoas̈h jahuen queena jacon jahuéquibo ati jahuequescamabi iqui, tsonbira amayamatima iqui. Jaticas̈hbira jascara aresti jacon shinanya iti jahuequescamabi iqui, jahuequescarainoas̈h picota joni inonbi. Huestiora huestiorabora jahuéqui ati shinanya iqui; jains̈hon onanribique jahueratoqui jacon iqui jainoas̈h jaconma iqui is̈hon. Ja copira huetsa jonibires inonbi non jato jaconharesti iqui, non huetsabi non acai quescaaquin.","Huestiora huestíorabora jati jahuequescamabi iqui, tsonbira retetima iqui, jainoas̈h jahuen queena jacon jahuéqui ati. Jainoas̈hshibi quiquinbiresi jatoqui chipoti iqui, tsonbi jaconmatima shinanas̈h.","Tsonbira huetsa joni, yoinna acai quescaaquin jaconmaquin masá tenemati yamaque."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_shp.xml","speakers":"https://en.wikipedia.org/wiki/Shipibo-Conibo_language","glottolog":"https://glottolog.org/resource/languoid/id/ship1254"}},{"name":"Tzotzil","aka":["Bats'i k'op"],"family":"Mayan","branch":"Cholan-Tzeltalan","script":"Latin","lat":16.6362,"lon":-92.7388,"speakers":550000,"region":"Americas","samples":["Skotol vinik o ants ta spejel balumile k’olem x-hayan i ko’ol ta sch’ulal i sderechoetik i, skotol k’ux-elan oyike oy srasonik y slekilalik, sventa skuxijik leknóo ta ju jun ju ju vo.","Skotol gente oy ta sderecho skuxij libre xanab ja’nab ja’tsa bu te sk’ane i seguro s-oyij.","Muk mu’ch’u sventa sta tsakel i chukel ni nutsel ta yanxa nom oxiltik."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_tzc.xml","speakers":"https://en.wikipedia.org/wiki/Tzotzil_language","glottolog":"https://glottolog.org/resource/languoid/id/tzot1259"}},{"name":"Asháninka","aka":["Ashaninka"],"family":"Arawakan","branch":"Southern Maipuran","script":"Latin","lat":-11.9311,"lon":-73.9073,"speakers":35000,"region":"Americas","samples":["Aquempetavacaajeita maaroni atiri. Timatsi aquenqueshirejeitantari maaroni, timatsi amejeitari, ayojeiti paitarica ocameetsati antajeitiri: te oncameetsateji intsaneapitsajeiteero itsipapee. Te oncameetsateji imperanajeitee, te oncameetsateji iroashinoncaajeitee, irointi ocameetsati aacameetsatavacaajeitea.","Te oncameetsateji iroyeetee, te oncameetsateji iroiminquiashiyeetee, te oncameetsateji iroashinonqueetee","Te oncameetsateji iroatsinayeeteri atiri, te oncameetsateji impasanatapiniterj, te oncameetsateji iroashinoqueeteri, te oncameetsatej i impashiventacayeari"],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_cni.xml","speakers":"https://en.wikipedia.org/wiki/Ash%C3%A1ninka_language","glottolog":"https://glottolog.org/resource/languoid/id/asha1243"}},{"name":"Maori","aka":["Māori","Te reo Māori"],"family":"Austronesian","branch":"Polynesian","script":"Latin","lat":-38.2881,"lon":176.541,"speakers":50000,"region":"Oceania","samples":["Ko te katoa o nga tangata i te whanaungatanga mai e watea ana i nga here katoa; e tauriterite ana hoki nga mana me nga tika. E whakawhiwhia ana hoki ki a ratou te ngakau whai whakaaro me te hinengaro mohio ki te tika me te he, a e tika ana kia meinga te mahi a tetahi ki tetahi me ma roto atu i te wairua o te noho tahi, ano he teina he tuakana i ringa i te whakaaro kotahi.","Ko ia tangata e whai take ana ki te mauri ora, me watea i nga tikanga tere, me maru hoki ia i raro i te mana o te ture.","Kaua tetahi tangata e noho pononga a ko nga tikanga whakapononga i te tangata me takahi rawa atu."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_mri.xml","speakers":"https://en.wikipedia.org/wiki/M%C4%81ori_language","glottolog":"https://glottolog.org/resource/languoid/id/maor1246"}},{"name":"Samoan","aka":["Gagana Sāmoa"],"family":"Austronesian","branch":"Polynesian","script":"Latin","lat":-13.92,"lon":-171.83,"speakers":430000,"region":"Oceania","samples":["O tagata soifua uma ua saoloto lo latou fananau mai, ma e tutusa o latou tulaga aloaia faapea a latou aia tatau. Ua faaeeina atu i a latou le mafaufau lelei ma le loto fuatiaifo ma e tatau ona faatino le agaga faauso i le va o le tasi i le isi,","O tagata uma taitoatasi e i ai lana aia tatau e soifua ma ola ai, o lona saolotoga faapea lona malu puipuia.","E leai se tagata e tatau ona saisaitia faapagota i se faiga saua, taofia pe faaaunuua i se isi atunuu."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_smo.xml","speakers":"https://en.wikipedia.org/wiki/Samoan_language","glottolog":"https://glottolog.org/resource/languoid/id/samo1305"}},{"name":"Tongan","aka":["Lea faka-Tonga"],"family":"Austronesian","branch":"Polynesian","script":"Latin","lat":-21.17,"lon":-175.25,"speakers":187000,"region":"Oceania","samples":["Ko e kotoa ‘o ha’a tangata ‘oku fanau’i mai ‘oku tau’ataina pea tatau ‘i he ngeia mo e ngaahi totonu. Na’e fakanaunau’i kinautolu ‘aki ‘a e ‘atamai mo e konisenisi pea ‘oku totonu ke nau feohi ‘i he laumalie ‘o e nofo fakatautehina.","‘Oku ‘a e tokotaha kotoa pe ‘a e totonu ke ne mo’ui, ke tau’ataina ‘a ‘ene ngaue’aki hono taimi mo malu ‘a ‘ene mo’ui mo hono sino.","‘E ‘ikai ke ngofua ke puke pe fakahu pilisone ta’efakalao, tauhi pilisone ta’efakalao pe fakahee’i ta’efakalao ha taha."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_ton.xml","speakers":"https://en.wikipedia.org/wiki/Tongan_language","glottolog":"https://glottolog.org/resource/languoid/id/tong1325"}},{"name":"Fijian","aka":["Na vosa vakaViti"],"family":"Austronesian","branch":"Oceanic","script":"Latin","lat":-18.0,"lon":178.33,"speakers":339210,"region":"Oceania","samples":["Era sucu ena galala na tamata yadua, era tautauvata ena nodra dokai kei na nodra dodonu. E tiko na nodra vakasama kei na nodra lewaeloma, sa dodonu mera veidokadokai ena yalo ni veitacini.","Na tamata kece e dodonu me bula, me galala, me taqomaki tale ga.","Me kua ni dua e vesu, qaqauraki, se me lesavi vakailoa"],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_fij.xml","speakers":"https://en.wikipedia.org/wiki/Fijian_language","glottolog":"https://glottolog.org/resource/languoid/id/fiji1243"}},{"name":"Hawaiian","aka":["ʻŌlelo Hawaiʻi"],"family":"Austronesian","branch":"Polynesian","script":"Latin","lat":19.6297,"lon":-155.43,"speakers":300,"region":"Oceania","samples":["Hānau kū’oko’a ‘ia nā kānaka apau loa, a ua kau like ka hanohano a me nā pono kīvila ma luna o kākou pākahi. Ua ku’u mai ka no’ono’o pono a me ka ‘ike pono ma luna o kākou, no laila, e aloha kākou kekahi i kekahi.","Ua noa i nā kānaka apau ke ola, ka mōhalu, a me ka maluhia.","E ‘ike ‘ia nā kānaka ma nā wahi apau, he kanaka i ka malu o ke kānāwai."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_haw.xml","speakers":"https://en.wikipedia.org/wiki/Hawaiian_language","glottolog":"https://glottolog.org/resource/languoid/id/hawa1245"}},{"name":"Tahitian","aka":["Reo Tahiti"],"family":"Austronesian","branch":"Polynesian","script":"Latin","lat":-17.6485,"lon":-149.45,"speakers":68260,"region":"Oceania","samples":["E fanauhia te tā'āto'ara'a o te ta'ata-tupu ma te ti'amā e te ti'amanara'a 'aifaito. Ua 'ī te mana'o pa'ari e i te manava e ma te 'a'au taea'e 'oia ta ratou ha'a i rotopū ia ratou iho, e ti'a ai;","'E ti'amanara'a to te ta'ata-tupu ato'a i te ora, i te ti'amāra'a e i te orara'a pano'ono'o 'ore.","'Eiaha roa te ta'ata ia tape'ahia, ia tamauhia i te 'auri 'aorc ra ia tuvaruhia ma te tumu 'ore."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_tah.xml","speakers":"https://en.wikipedia.org/wiki/Tahitian_language","glottolog":"https://glottolog.org/resource/languoid/id/tahi1242"}},{"name":"Tok Pisin","aka":["Pidgin"],"family":"Indo-European","branch":"Germanic","script":"Latin","lat":-9.4197,"lon":147.303,"speakers":130000,"region":"Oceania","samples":["Yumi olgeta mama karim umi long stap fri na wankain long wei yumi lukim i gutpela na strepela tru. Uumi olgeta igat ting ting bilong wanem samting I rait na rong na mipela olgeta I mas mekim gutpela pasin long ol narapela long tingting bilong brata susa.","Yumi olgeta igat rait long stap laip, fri na sef.","Olgeta manmeri long olgeta hap igat rait long luksave blong lo."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_tpi.xml","speakers":"https://en.wikipedia.org/wiki/Tok_Pisin","glottolog":"https://glottolog.org/resource/languoid/id/tokp1240"}},{"name":"Bislama","aka":[],"family":"Indo-European","branch":"Germanic","script":"Latin","lat":-15.4,"lon":166.89,"speakers":10000,"region":"Oceania","samples":["Evri man mo woman i bon fri mo ikwol long respek mo ol raet. Oli gat risen mo tingting mo oli mas tritim wanwan long olgeta olsem ol brata mo sista.","Evriwan i gat raet blong laef, fridommo sekuriti blong man mo woman.","Evriwan i gat raet blong narafala man i luksave hem olsem wan man o woman we i stap anda long loa."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_bis.xml","speakers":"https://en.wikipedia.org/wiki/Bislama","glottolog":"https://glottolog.org/resource/languoid/id/bisl1239"}},{"name":"Pijin","aka":["Solomons Pijin"],"family":"Indo-European","branch":"Germanic","script":"Latin","lat":-9.567,"lon":160.137,"speakers":null,"region":"Oceania","samples":["Evri man en mere olketa born frii en ikwol lo digniti en raits blo olketa. Olketa evriwan olketa garem maeni fo tingting en olketa sapos fo treatim isada wittim spirit blo bradahood.","Evriwan i garem rait lo laef, friidom en sekuriti blo olketa.","Evri wan i garem rait lo eniwea fo loa luk savve lo olketa."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_pis.xml","speakers":"https://en.wikipedia.org/wiki/Pijin_language","glottolog":"https://glottolog.org/resource/languoid/id/piji1239"}},{"name":"Chamorro","aka":["Chamoru"],"family":"Austronesian","branch":"Malayo-Polynesian","script":"Latin","lat":13.438,"lon":144.7447,"speakers":58000,"region":"Oceania","samples":["Todo taotao siha man mafanago libertao yan pareho gi dignidad yan derecho siha, man manae siha hinaso yan consiencia yan debe de ufatinas contra uno yan otro gi un espiritun chumelo.","Todo mangai derecho pot linala, libertad yan seguridad i persona.","Taya sina na sometido nu i arbitrario na inaresta, detension pat destierro."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_cha.xml","speakers":"https://en.wikipedia.org/wiki/Chamorro_language","glottolog":"https://glottolog.org/resource/languoid/id/cham1312"}},{"name":"Marshallese","aka":["Kajin M̧ajeļ"],"family":"Austronesian","branch":"Micronesian","script":"Latin","lat":8.72,"lon":167.73,"speakers":55000,"region":"Oceania","samples":["Armij otemjej rej rujlok ilo anemkwoj im jonon utiej eo im maron ko air wot juon. Emwij lelok non ir maron in bukot non ir make im bareinwot boklikot kin men ko rej tomaki im bwe jerbal non dron ilo juon jitobon jimpenjatin.","Kajojo armij eor an maron bwe en mour ilo mour in, bwe en wor an anemkwoj im bwe en jokane ilo e make.","Kajojo armij eor an maron bwe en wor watoke ijoko otemjej ke e ej bar juon armij iman kien."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_mah.xml","speakers":"https://en.wikipedia.org/wiki/Marshallese_language","glottolog":"https://glottolog.org/resource/languoid/id/mars1254"}},{"name":"Pintupi","aka":["Pintupi-Luritja"],"family":"Pama-Nyungan","branch":"Desert Nyungic","script":"Latin","lat":-23.2963,"lon":130.643,"speakers":null,"region":"Oceania","samples":["Nganana maru tjuta, tjulkura tjuta, manta yurungka parrari nyinapayi tjutanya liipulala nyinanyi, nganana yanangu maru tjuta wiya kuyakuya. Yuwankarrangkuya palya nintingku kulini. Tjanaya palya kutjupa tjutaku tjukarurru nyinanytjaku, walytja tjuta nguwanpa, mingarrtjuwiya. Tjungungku palyangku kurrunpa kutjungku. Wangka ngaangku nganananya tjakultjunanyi rapa ngaranytjaku kutjupa tjuta nguwanpa.","Pana winkiku ngaranyi nyinanytjaku tjukarurru. Watingku kungkangku wiya warrkira pungkunytjaku. Watingku wiya pungkunytjaku kungka, pipirri. Wiya kutjupa mirri pungkunytjaku, wiya kuyara pungkunytjaku. Yantayantara marangku purinypangkula kanyintjaku. Wangka ngaangku nganananya tjakultjunanyi kutjupa tjuta nguwanpa palya nyinanytjaku.","Wiyalpi ngaranyi, nyinyipungkunytjaku yitjipungkunytjaku. Tjukarurruwanangku pungkunytjawiyangku, palyangku yantantantjaku. Wiyalpi pungkunytjaku kutjupa kutjupa tjutanya."],"src":{"text":"https://github.com/unicode-org/udhr/blob/main/data/udhr/udhr_piu.xml","speakers":"https://en.wikipedia.org/wiki/Pintupi_language","glottolog":"https://glottolog.org/resource/languoid/id/pint1250"}}];
